procedure:public.apply_booking_transitio.source_code:
declare
  v_booking bookings%rowtype;
  -- Captured BEFORE the update: `returning * into v_booking` overwrites the
  -- variable with the new row, so reading v_booking.status afterwards would
  -- record previous_status = new_status on every history row and quietly destroy
  -- the trail a dispute depends on.
  v_from    booking_status;
begin
  select * into v_booking from bookings where id = p_booking_id for update;
  if not found then
    raise exception 'Booking not found' using errcode = 'no_data_found';
  end if;

  -- Idempotent no-op: a retried request that already achieved its goal returns
  -- the booking rather than failing. This is what makes a flaky network safe.
  if v_booking.status = p_to then
    return v_booking;
  end if;

  if not booking_transition_allowed(v_booking.status, p_to, p_actor) then
    raise exception 'Cannot move a booking from % to % as %', v_booking.status, p_to, p_actor
      using errcode = 'invalid_parameter_value';
  end if;

  v_from := v_booking.status;

  update bookings
     set status = p_to,
         -- Server clocks only. A client-supplied "I started at" is a claim, not
         -- a fact, and these timestamps feed payout and dispute timelines.
         pro_confirmed_at  = case when p_to = 'confirmed' then now() else pro_confirmed_at end,
         pro_declined_at   = case when p_to = 'declined_by_pro' then now() else pro_declined_at end,
         started_at        = case when p_to = 'in_progress' and started_at is null then now()
                                  else started_at end,
         work_submitted_at = case when p_to = 'completion_submitted' then now()
                                  else work_submitted_at end,
         completed_at      = case when p_to = 'completed' then now() else completed_at end,
         cancelled_at      = case when p_to in ('cancelled_by_customer','cancelled_by_pro',
                                                'declined_by_pro','expired')
                                  then now() else cancelled_at end,
         cancelled_by      = case when p_to = 'cancelled_by_customer' then 'customer'::cancelling_party
                                  when p_to in ('cancelled_by_pro','declined_by_pro') then 'pro'::cancelling_party
                                  when p_to = 'expired' then 'system'::cancelling_party
                                  else cancelled_by end,
         updated_at = now()
   where id = p_booking_id
   returning * into v_booking;

  insert into booking_status_history (booking_id, actor_id, previous_status, new_status, note, metadata)
  values (p_booking_id, p_actor_id, v_from, p_to, p_note, p_metadata);

  insert into audit_events (actor_id, actor_kind, action, entity_type, entity_id, metadata)
  values (
    p_actor_id,
    case p_actor when 'system' then 'system' else 'user' end,
    'booking.' || p_to::text, 'booking', p_booking_id,
    p_metadata || jsonb_build_object('actor', p_actor::text)
  );

  -- A terminal booking releases the pro's calendar.
  if booking_is_terminal(p_to) then
    delete from pro_time_blocks where booking_id = p_booking_id;
  end if;

  return v_booking;
end;

