         -- a fact, and these timestamps feed payout and dispute timelines.
         pro_confirmed_at  = case when p_to = 'confirmed' then now() else pro_confirmed_at end,
         pro_declined_at   = case when p_to = 'declined_by_pro' then now() else pro_declined_at end,
         started_at        = case when p_to = 'in_progress' and started_at is null then now()
