  values (p_booking_id, p_actor_id, v_from, p_to, p_note, p_metadata);

  insert into audit_events (actor_id, actor_kind, action, entity_type, entity_id, metadata)
  values (
    p_actor_id,
    case p_actor when 'system' then 'system' else 'user' end,
