    p_metadata || jsonb_build_object('actor', p_actor::text)
  );

  -- A terminal booking releases the pro's calendar.
  if booking_is_terminal(p_to) then
    delete from pro_time_blocks where booking_id = p_booking_id;
  end if;

  return v_booking;
end;
$function$

procedure:public.apply_referral_code(tex.source_code:
declare
  v_referrer uuid;
  v_code     text := upper(btrim(coalesce(p_code, '')));
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;
  if v_code = '' then
    raise exception 'Enter a referral code'
      using errcode = 'invalid_parameter_value', hint = 'code_blank';
  end if;

  select id into v_referrer from profiles where referral_code = v_code;
  if v_referrer is null then
    raise exception 'That referral code is not recognised'
      using errcode = 'invalid_parameter_value', hint = 'code_unknown';
  end if;
  if v_referrer = auth.uid() then
    raise exception 'You cannot use your own referral code'
      using errcode = 'invalid_parameter_value', hint = 'code_self';
  end if;

  insert into referrals (referrer_id, referred_id, code_used)
  values (v_referrer, auth.uid(), v_code)
  on conflict (referred_id) do nothing;

  if not found then
    raise exception 'You have already used a referral code'
      using errcode = 'invalid_parameter_value', hint = 'already_referred';
  end if;
end;

