procedure:public.assign_job_directly(uui.source_code:
declare
  v_caller      uuid := auth.uid();
  v_job         jobs%rowtype;
  v_quote       price_quotes%rowtype;
  v_existing    bookings%rowtype;
  v_match_id    uuid;
  v_booking_id  uuid;
  v_start       timestamptz;
  v_end         timestamptz;
  v_block_range tstzrange;
  v_prep        interval := interval '30 minutes';
  v_window      interval;
  v_attempt     int;
  v_suppressed  int := 0;
  v_was_market  boolean;
begin
  if v_caller is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  -- Idempotency first, before any lock or check. A double-tapped button and a
  -- retry after a timeout must both land on the same booking rather than
  -- racing to create a second one.
  select b.* into v_existing
  from bookings b
  join audit_events a
    on a.entity_id = b.id
   and a.action = 'booking.created'
   and a.metadata ->> 'idempotency_key' = p_idempotency_key
  limit 1;

  if found then
    return query select v_existing.id, v_existing.status, false;
    return;
  end if;

  -- Everything after this serialises on the job row, so two simultaneous
  -- assignments of DIFFERENT pros cannot both proceed.
  select * into v_job from jobs where id = p_job_id for update;
  if not found then
    raise exception 'Job not found' using errcode = 'no_data_found';
  end if;

  if v_job.customer_id <> v_caller then
    raise exception 'Only the job owner may assign a pro' using errcode = '42501';
  end if;

  -- A pro cannot route work to themselves.
  if p_pro_id = v_caller then
    raise exception 'You cannot assign a job to yourself' using errcode = '42501';
  end if;

  -- Assignable means priced (never published) or published (being converted).
  -- Anything further along already has a pro or is finished.
  if v_job.status not in ('priced', 'published') then
    raise exception 'This job can no longer be assigned (status %)', v_job.status
      using errcode = 'invalid_parameter_value';
  end if;

  v_was_market := v_job.status = 'published';

  -- The booking columns are NOT NULL, so these are genuine preconditions rather
  -- than defensive checks. A job with no address cannot be worked at, and a job
  -- with no requested time has no schedule to book or to check availability
  -- against.
  if v_job.address_id is null or v_job.service_location is null then
    raise exception 'This job needs a service address before a pro can be assigned'
      using errcode = 'invalid_parameter_value', hint = 'address_required';
  end if;
  if v_job.requested_service_start is null then
    raise exception 'This job needs a requested time before a pro can be assigned'
      using errcode = 'invalid_parameter_value', hint = 'schedule_required';
  end if;

  -- Price: loaded, never supplied. There is no monetary parameter on this
  -- function, so a client value cannot reach a price column by any route.
  if v_job.price_quote_id is null then
    raise exception 'This job has no locked price' using errcode = 'invalid_parameter_value',
      hint = 'no_price';
  end if;
  if not quote_is_current(v_job.price_quote_id) then
    raise exception 'This price is out of date and must be refreshed before assigning'
      using errcode = 'invalid_parameter_value', hint = 'quote_expired';
  end if;
  select * into v_quote from price_quotes where id = v_job.price_quote_id;

  -- Eligibility, through the SAME definition marketplace publication uses:
  -- approval, suspension, accepting-work, category, PostGIS service area,
  -- licence and insurance, skills, workload limit, pause state, blocks. Reusing
  -- it is what stops the two modes drifting into different notions of who may
  -- do the work.
  if not exists (
    select 1 from eligible_pros_for_job(p_job_id) e where e.pro_id = p_pro_id
  ) then
    raise exception 'That pro cannot take this job'
      using errcode = 'invalid_parameter_value', hint = 'pro_ineligible';
  end if;

  v_start := v_job.requested_service_start;
  v_end   := v_start + make_interval(mins => v_job.estimated_duration_minutes);

  -- Availability is rechecked here rather than trusted from a browse listing,
  -- which may be seconds or hours stale.
  if not pro_is_available(p_pro_id, v_start,
                          v_job.estimated_duration_minutes, v_job.final_priority) then
    raise exception 'That pro is not available at the requested time'
      using errcode = 'invalid_parameter_value', hint = 'pro_unavailable';
  end if;

  v_window := make_interval(mins => coalesce(
    business_rule_int(active_business_rule_set(), 'pro_decline_window_minutes')::int, 120));

  -- The match. Direct assignment does NOT require prior interest, so this row
  -- may not exist yet; when it does — the pro was eligible for a published job
  -- — it is promoted rather than duplicated.
  insert into job_matches (job_id, pro_id, status, job_version, eligibility_snapshot)
  values (p_job_id, p_pro_id, 'selected', coalesce(v_job.priority_rule_version, 1),
          jsonb_build_object('mode', 'direct', 'evaluated_at', now()))
  on conflict (job_id, pro_id) do update
     set status = 'selected', updated_at = now()
  returning id into v_match_id;

  -- Converting a published job to direct: every other opportunity is closed in
  -- this same transaction. Two live modes on one job is exactly the leakage the
  -- mode column exists to prevent.
  update job_matches
     set status = 'not_selected', updated_at = now()
   where job_id = p_job_id
     and id <> v_match_id
     and status not in ('withdrawn', 'expired', 'not_selected');
  get diagnostics v_suppressed = row_count;

  insert into bookings (
    job_id, match_id, customer_id, pro_id, category_id, price_quote_id,
    status, scheduled_start, scheduled_end, address_id, service_location,
    business_rule_set_id, cancellation_policy_id, decline_deadline
  ) values (
    v_job.id, v_match_id, v_job.customer_id, p_pro_id, v_job.category_id,
    -- The authoritative pricing record, referenced. Not copied field by field
    -- from anything the caller sent.
    v_job.price_quote_id, 'pending_pro_confirmation',
    v_start, v_end, v_job.address_id, v_job.service_location,
    v_quote.business_rule_set_id,
    (select id from cancellation_policies where status = 'active' limit 1),
    now() + v_window
  )
  returning id into v_booking_id;

  v_block_range := tstzrange(v_start - v_prep, v_end + v_prep, '[)');
  insert into pro_time_blocks (pro_id, booking_id, kind, time_range)
  values (p_pro_id, v_booking_id, 'booking', v_block_range);

  update jobs
     set assignment_mode = 'direct',
         status          = 'pending_selection',
         closed_at       = now(),
         updated_at      = now()
   where id = p_job_id;

  update soft_holds set released_at = now() where job_id = p_job_id and released_at is null;
  delete from pro_time_blocks
   where kind = 'soft_hold'
     and hold_id in (select id from soft_holds where job_id = p_job_id);

  select coalesce(max(attempt_number), 0) + 1 into v_attempt
    from selection_attempts where job_id = p_job_id;
  insert into selection_attempts (job_id, match_id, pro_id, booking_id, attempt_number)
  values (p_job_id, v_match_id, p_pro_id, v_booking_id, v_attempt);

  insert into booking_status_history (booking_id, actor_id, previous_status, new_status, note)
  values (v_booking_id, v_caller, null, 'pending_pro_confirmation',
          'Customer assigned pro directly');

  insert into job_match_events (match_id, actor_id, previous_status, new_status, note)
  values (v_match_id, v_caller, null, 'selected', 'Direct assignment');

  -- Audit carries the mode and the identifiers, and nothing about the job's
  -- content: no description, no address, no photograph path.
  insert into audit_events (actor_id, action, entity_type, entity_id, metadata)
  values (v_caller, 'booking.created', 'booking', v_booking_id,
    jsonb_build_object(
      'idempotency_key',   p_idempotency_key,
      'job_id',            p_job_id,
      'match_id',          v_match_id,
      'pro_id',            p_pro_id,
      'price_quote_id',    v_job.price_quote_id,
      'assignment_mode',   'direct',
      'converted_from',    case when v_was_market then 'marketplace' else null end,
      'suppressed_matches', v_suppressed,
      'attempt',           v_attempt));

  -- Exactly one pro is told. Idempotent by the outbox uniqueness key.
  perform queue_booking_notification(v_booking_id, p_pro_id, 'pro_selected', 'high');

  -- Pros whose opportunity was suppressed by the conversion are told the job
  -- closed — they already knew it existed, and silence would leave it sitting
  -- in their list forever. Nobody who did not already know is told anything.
  insert into notification_outbox (recipient_user_id, event_type, entity_type, entity_id,
                                   event_version, priority, payload)
  select m.pro_id, 'job_closed', 'job', p_job_id, v_attempt, 'normal',
         jsonb_build_object('job_id', p_job_id)
  from job_matches m
  where m.job_id = p_job_id and m.id <> v_match_id and m.status = 'not_selected'
  on conflict (recipient_user_id, event_type, entity_id, event_version) do nothing;

  return query select v_booking_id, 'pending_pro_confirmation'::booking_status, true;
end;

procedure:public.assign_job_directly(uui.definition:
CREATE OR REPLACE FUNCTION public.assign_job_directly(p_job_id uuid, p_pro_id uuid, p_idempotency_key text)
 RETURNS TABLE(booking_id uuid, booking_status public.booking_status, was_created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller      uuid := auth.uid();
  v_job         jobs%rowtype;
  v_quote       price_quotes%rowtype;
  v_existing    bookings%rowtype;
  v_match_id    uuid;
  v_booking_id  uuid;
  v_start       timestamptz;
  v_end         timestamptz;
  v_block_range tstzrange;
  v_prep        interval := interval '30 minutes';
  v_window      interval;
  v_attempt     int;
  v_suppressed  int := 0;
  v_was_market  boolean;
begin
  if v_caller is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  -- Idempotency first, before any lock or check. A double-tapped button and a
  -- retry after a timeout must both land on the same booking rather than
  -- racing to create a second one.
  select b.* into v_existing
  from bookings b
  join audit_events a
    on a.entity_id = b.id
   and a.action = 'booking.created'
   and a.metadata ->> 'idempotency_key' = p_idempotency_key
  limit 1;

  if found then
    return query select v_existing.id, v_existing.status, false;
    return;
  end if;

  -- Everything after this serialises on the job row, so two simultaneous
  -- assignments of DIFFERENT pros cannot both proceed.
  select * into v_job from jobs where id = p_job_id for update;
  if not found then
    raise exception 'Job not found' using errcode = 'no_data_found';
  end if;

  if v_job.customer_id <> v_caller then
    raise exception 'Only the job owner may assign a pro' using errcode = '42501';
  end if;

  -- A pro cannot route work to themselves.
  if p_pro_id = v_caller then
    raise exception 'You cannot assign a job to yourself' using errcode = '42501';
  end if;

  -- Assignable means priced (never published) or published (being converted).
  -- Anything further along already has a pro or is finished.
  if v_job.status not in ('priced', 'published') then
    raise exception 'This job can no longer be assigned (status %)', v_job.status
      using errcode = 'invalid_parameter_value';
  end if;

  v_was_market := v_job.status = 'published';

  -- The booking columns are NOT NULL, so these are genuine preconditions rather
  -- than defensive checks. A job with no address cannot be worked at, and a job
  -- with no requested time has no schedule to book or to check availability
  -- against.
  if v_job.address_id is null or v_job.service_location is null then
    raise exception 'This job needs a service address before a pro can be assigned'
      using errcode = 'invalid_parameter_value', hint = 'address_required';
  end if;
  if v_job.requested_service_start is null then
    raise exception 'This job needs a requested time before a pro can be assigned'
      using errcode = 'invalid_parameter_value', hint = 'schedule_required';
  end if;

  -- Price: loaded, never supplied. There is no monetary parameter on this
  -- function, so a client value cannot reach a price column by any route.
  if v_job.price_quote_id is null then
    raise exception 'This job has no locked price' using errcode = 'invalid_parameter_value',
      hint = 'no_price';
  end if;
  if not quote_is_current(v_job.price_quote_id) then
    raise exception 'This price is out of date and must be refreshed before assigning'
      using errcode = 'invalid_parameter_value', hint = 'quote_expired';
  end if;
  select * into v_quote from price_quotes where id = v_job.price_quote_id;

  -- Eligibility, through the SAME definition marketplace publication uses:
  -- approval, suspension, accepting-work, category, PostGIS service area,
  -- licence and insurance, skills, workload limit, pause state, blocks. Reusing
  -- it is what stops the two modes drifting into different notions of who may
  -- do the work.
  if not exists (
    select 1 from eligible_pros_for_job(p_job_id) e where e.pro_id = p_pro_id
  ) then
    raise exception 'That pro cannot take this job'
      using errcode = 'invalid_parameter_value', hint = 'pro_ineligible';
  end if;

  v_start := v_job.requested_service_start;
  v_end   := v_start + make_interval(mins => v_job.estimated_duration_minutes);

  -- Availability is rechecked here rather than trusted from a browse listing,
  -- which may be seconds or hours stale.
  if not pro_is_available(p_pro_id, v_start,
                          v_job.estimated_duration_minutes, v_job.final_priority) then
    raise exception 'That pro is not available at the requested time'
      using errcode = 'invalid_parameter_value', hint = 'pro_unavailable';
  end if;

  v_window := make_interval(mins => coalesce(
    business_rule_int(active_business_rule_set(), 'pro_decline_window_minutes')::int, 120));

  -- The match. Direct assignment does NOT require prior interest, so this row
  -- may not exist yet; when it does — the pro was eligible for a published job
  -- — it is promoted rather than duplicated.
  insert into job_matches (job_id, pro_id, status, job_version, eligibility_snapshot)
  values (p_job_id, p_pro_id, 'selected', coalesce(v_job.priority_rule_version, 1),
          jsonb_build_object('mode', 'direct', 'evaluated_at', now()))
  on conflict (job_id, pro_id) do update
     set status = 'selected', updated_at = now()
  returning id into v_match_id;

  -- Converting a published job to direct: every other opportunity is closed in
  -- this same transaction. Two live modes on one job is exactly the leakage the
  -- mode column exists to prevent.
  update job_matches
     set status = 'not_selected', updated_at = now()
   where job_id = p_job_id
     and id <> v_match_id
     and status not in ('withdrawn', 'expired', 'not_selected');
  get diagnostics v_suppressed = row_count;

  insert into bookings (
    job_id, match_id, customer_id, pro_id, category_id, price_quote_id,
    status, scheduled_start, scheduled_end, address_id, service_location,
    business_rule_set_id, cancellation_policy_id, decline_deadline
  ) values (
    v_job.id, v_match_id, v_job.customer_id, p_pro_id, v_job.category_id,
    -- The authoritative pricing record, referenced. Not copied field by field
    -- from anything the caller sent.
    v_job.price_quote_id, 'pending_pro_confirmation',
    v_start, v_end, v_job.address_id, v_job.service_location,
    v_quote.business_rule_set_id,
    (select id from cancellation_policies where status = 'active' limit 1),
    now() + v_window
  )
  returning id into v_booking_id;

  v_block_range := tstzrange(v_start - v_prep, v_end + v_prep, '[)');
  insert into pro_time_blocks (pro_id, booking_id, kind, time_range)
  values (p_pro_id, v_booking_id, 'booking', v_block_range);

  update jobs
     set assignment_mode = 'direct',
         status          = 'pending_selection',
         closed_at       = now(),
         updated_at      = now()
   where id = p_job_id;

  update soft_holds set released_at = now() where job_id = p_job_id and released_at is null;
  delete from pro_time_blocks
   where kind = 'soft_hold'
     and hold_id in (select id from soft_holds where job_id = p_job_id);

  select coalesce(max(attempt_number), 0) + 1 into v_attempt
    from selection_attempts where job_id = p_job_id;
  insert into selection_attempts (job_id, match_id, pro_id, booking_id, attempt_number)
  values (p_job_id, v_match_id, p_pro_id, v_booking_id, v_attempt);

  insert into booking_status_history (booking_id, actor_id, previous_status, new_status, note)
  values (v_booking_id, v_caller, null, 'pending_pro_confirmation',
          'Customer assigned pro directly');

  insert into job_match_events (match_id, actor_id, previous_status, new_status, note)
  values (v_match_id, v_caller, null, 'selected', 'Direct assignment');

  -- Audit carries the mode and the identifiers, and nothing about the job's
  -- content: no description, no address, no photograph path.
  insert into audit_events (actor_id, action, entity_type, entity_id, metadata)
  values (v_caller, 'booking.created', 'booking', v_booking_id,
    jsonb_build_object(
      'idempotency_key',   p_idempotency_key,
      'job_id',            p_job_id,
      'match_id',          v_match_id,
      'pro_id',            p_pro_id,
      'price_quote_id',    v_job.price_quote_id,
      'assignment_mode',   'direct',
      'converted_from',    case when v_was_market then 'marketplace' else null end,
      'suppressed_matches', v_suppressed,
      'attempt',           v_attempt));

  -- Exactly one pro is told. Idempotent by the outbox uniqueness key.
  perform queue_booking_notification(v_booking_id, p_pro_id, 'pro_selected', 'high');

  -- Pros whose opportunity was suppressed by the conversion are told the job
  -- closed — they already knew it existed, and silence would leave it sitting
  -- in their list forever. Nobody who did not already know is told anything.
  insert into notification_outbox (recipient_user_id, event_type, entity_type, entity_id,
                                   event_version, priority, payload)
  select m.pro_id, 'job_closed', 'job', p_job_id, v_attempt, 'normal',
         jsonb_build_object('job_id', p_job_id)
  from job_matches m
  where m.job_id = p_job_id and m.id <> v_match_id and m.status = 'not_selected'
  on conflict (recipient_user_id, event_type, entity_id, event_version) do nothing;

  return query select v_booking_id, 'pending_pro_confirmation'::booking_status, true;
end;
$function$

procedure:public.auth_is_anonymous().source_code:
select case
  when auth.uid() is null then true
  when coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) then true
  else coalesce((select p.is_anonymous from profiles p where p.id = auth.uid()), true)
end;

procedure:public.begin_stripe_event(text.source_code:
declare
  v_status text;
begin
  if not is_trusted_caller() then
    raise exception 'Only the server may record a Stripe event'
      using errcode = '42501';
  end if;

  insert into stripe_events (event_id, type, livemode, api_version, payload, attempts)
  values (p_event_id, p_type, p_livemode, p_api_version, p_payload, 1)
  on conflict (event_id) do update
     set attempts = stripe_events.attempts + 1
  returning status into v_status;

  -- Already done. The retry is acknowledged and nothing happens again.
  return v_status is distinct from 'processed';
end;

