procedure:public.bookings_mode_consisten.source_code:
declare v_mode job_assignment_mode; v_match_status match_status;
begin
  select assignment_mode into v_mode from jobs where id = new.job_id;
  if v_mode is null then return new; end if;

  select status into v_match_status from job_matches where id = new.match_id;

  -- A direct assignment promotes its match to `selected` in the same statement
  -- that creates the booking, so a booking on a direct job always has one. A
  -- marketplace booking requires the pro to have expressed interest first,
  -- which assign_job_directly() bypasses — and must only bypass in direct mode.
  if v_mode = 'direct' and v_match_status is distinct from 'selected' then
    raise exception 'A direct assignment must select its own match'
      using errcode = 'invalid_parameter_value';
  end if;

  return new;
end;

procedure:public.bookings_mode_consisten.definition:
