procedure:public.bookings_snapshot_immut.source_code:
begin
  if new.additional_time_rate_cents is distinct from old.additional_time_rate_cents
     or new.rate_currency is distinct from old.rate_currency
     or new.commission_bp is distinct from old.commission_bp
     or new.priority_uplift_bp is distinct from old.priority_uplift_bp then
    raise exception
      'The additional-time rate and commission snapshot are fixed when the '
      'booking is created and cannot be changed'
      using errcode = '42501';
  end if;
