procedure:public.bookings_snapshot_rate(.source_code:
declare
  v_rate      bigint;
  v_currency  text;
  v_comm      int;
  v_priority  job_priority;
  v_rules     category_pricing_rules%rowtype;
  v_quote_ccy text;
begin
  -- FOR UPDATE, so a pro saving a new rate at this instant waits for the
  -- booking rather than the booking reading a value that is about to change.
  select additional_time_rate_cents, rate_currency
    into v_rate, v_currency
    from pro_service_categories
   where pro_id = new.pro_id and category_id = new.category_id
     for update;

  if v_rate is null or v_rate <= 0 or v_currency is null or v_currency = '' then
    raise exception
      'This pro has not published an additional-time rate for this service, so '
      'the booking cannot be created'
      using errcode = 'invalid_parameter_value', hint = 'rate_required';
  end if;

  select currency into v_quote_ccy from price_quotes where id = new.price_quote_id;

  -- Refuse rather than convert. A mismatch means somebody's configuration is
  -- wrong, and guessing an exchange rate to paper over it would turn a visible
  -- error into an invisible one.
  if v_quote_ccy is not null and v_currency is distinct from v_quote_ccy then
    raise exception
      'The pro''s additional-time rate is in % but this booking is priced in %',
      v_currency, v_quote_ccy
      using errcode = 'invalid_parameter_value';
  end if;

  new.additional_time_rate_cents := v_rate;
  new.rate_currency := v_currency;

  v_comm := business_rule_int(new.business_rule_set_id, 'platform_commission_bp');
  if v_comm is null then
    raise exception 'No platform commission is configured for this booking''s rule set'
      using errcode = 'invalid_parameter_value';
  end if;
  if v_comm < 0 or v_comm >= 10000 then
    raise exception 'Commission of % bp is outside the permitted range [0,10000)', v_comm
      using errcode = 'invalid_parameter_value';
  end if;
  new.commission_bp := v_comm;

  select final_priority into v_priority from jobs where id = new.job_id;
  select * into v_rules
    from category_pricing_rules
   where rule_set_id = active_pricing_rule_set()
     and category_id = new.category_id;

  new.priority_uplift_bp := case
    when not found then 0
    when v_priority = 'soon'   then v_rules.soon_adjustment_bp
    when v_priority = 'urgent' then v_rules.urgent_adjustment_bp
    else 0
  end;

  return new;
end;

