from business_rule_values
where rule_set_id = p_rule_set_id and key = p_key;

procedure:public.business_rule_values_gu.source_code:
declare
  v int;
begin
  if new.key = 'platform_commission_bp' then
    begin
      v := (new.value #>> '{}')::int;
    exception when others then
      raise exception 'platform_commission_bp must be an integer number of basis points'
        using errcode = 'invalid_parameter_value';
    end;
    -- Strictly below 10000. At 10000 the additional-time gross-up divides by
    -- zero; above it the customer would pay less than the pro receives.
    if v < 0 or v >= 10000 then
      raise exception
        'platform_commission_bp must be in [0,10000); got %', v
        using errcode = 'invalid_parameter_value';
    end if;
  end if;

  if new.key = 'customer_fee_bp' then
    begin
      v := (new.value #>> '{}')::int;
    exception when others then
      raise exception 'customer_fee_bp must be an integer number of basis points'
        using errcode = 'invalid_parameter_value';
    end;
    if v < 0 then
      raise exception 'customer_fee_bp cannot be negative; got %', v
        using errcode = 'invalid_parameter_value';
    end if;
  end if;

  return new;
end;

