procedure:public.can_publish_job(uuid).source_code:
declare
  v_job jobs%rowtype;
begin
  select * into v_job from jobs where id = p_job_id;

  if not found or v_job.customer_id <> auth.uid() then
    -- Not found and not yours are deliberately the same answer: a probe must
    -- not be able to distinguish them.
    return query select false, 'not_found';
    return;
  end if;

  if not is_verified_customer() then
    perform audit_guest_denied('publish_job', p_job_id);
    return query select false, 'account_verification_required';
    return;
  end if;

  if v_job.price_quote_id is null then
    return query select false, 'no_price';
    return;
  end if;

  if v_job.status not in ('priced', 'published') then
    return query select false, 'wrong_status';
    return;
  end if;

  return query select true, null::text;
end;

