procedure:public.cancel_booking(uuid,tex.source_code:
declare
  v_caller uuid := auth.uid();
  v_b      bookings%rowtype;
  v_actor  booking_actor;
  v_target booking_status;
  v_from   booking_status;
begin
  select * into v_b from bookings where id = p_booking_id for update;
  if not found then raise exception 'Booking not found' using errcode = 'no_data_found'; end if;

  if v_b.customer_id = v_caller then
    v_actor := 'customer'; v_target := 'cancelled_by_customer';
  elsif v_b.pro_id = v_caller then
    v_actor := 'pro'; v_target := 'cancelled_by_pro';
  else
    raise exception 'Only a party to this booking may cancel it' using errcode = '42501';
  end if;

  v_from := v_b.status;

  -- Idempotent: if the booking is already in the target state,
  -- apply_booking_transition returns it unchanged and writes no history. Return
  -- immediately so the cancellation record and the notification are not
  -- duplicated by a retried request.
  if v_from = v_target then
    return v_b;
  end if;

  v_b := apply_booking_transition(p_booking_id, v_target, v_actor, v_caller,
                                  p_reason_code, jsonb_build_object('reason_code', p_reason_code));

  insert into booking_cancellations (
    booking_id, cancelled_by, actor_id, reason_code, explanation, previous_status,
    -- No fee is computed. The approved cancellation policy does not exist yet,
    -- and a number written here would become history nobody agreed to.
    policy_version, requires_payment_review
  ) values (
    p_booking_id, v_actor, v_caller, p_reason_code, p_explanation, v_from,
    null, true
  );

  if v_actor = 'pro' then
    -- A late decline. Same treatment: withdraw this pro so they are not offered
    -- the job again, restore the rivals subject to a fresh availability check,
    -- and republish. This also resolves the selection attempt.
    perform release_booking_and_reopen_job(p_booking_id, 'cancelled_by_pro', p_reason_code);
  else
    update selection_attempts
       set outcome = 'cancelled', outcome_reason = p_reason_code, resolved_at = now()
     where booking_id = p_booking_id and outcome = 'pending';

    -- The customer called it off. Close the job rather than sending their
    -- address back out to every eligible pro for work they no longer want.
    update jobs
       set status     = 'cancelled',
           closed_at  = coalesce(closed_at, now()),
           updated_at = now()
     where id = v_b.job_id
       and status not in ('completed', 'cancelled');
  end if;

  perform queue_booking_notification(
    p_booking_id,
    case when v_actor = 'customer' then v_b.pro_id else v_b.customer_id end,
    'booking_cancelled', 'high');

  return v_b;
end;

