procedure:public.complete_account_upgrad.source_code:
declare
  v_uid       uuid := auth.uid();
  v_job       jobs%rowtype;
  v_old_quote uuid;
  v_new_quote uuid;
  v_changed   boolean := false;
  v_ttl       int;
begin
  if v_uid is null then
    raise exception 'Not signed in' using errcode = '42501';
  end if;

  -- Verification is a fact about the account, established by the auth trigger.
  -- This function only observes it.
  if not is_verified_customer() then
    raise exception 'Verify your email or phone number to continue'
      using errcode = '42501', hint = 'account_verification_required';
  end if;

  -- Clear the expiry timer on everything this account owns. Safe to repeat.
  update jobs set guest_expires_at = null
   where customer_id = v_uid and guest_expires_at is not null;

  if p_job_id is null then
    return query select true, null::uuid, null::uuid, false, false;
    return;
  end if;

  select * into v_job from jobs where id = p_job_id for update;
  if not found then
    raise exception 'Job not found' using errcode = 'no_data_found';
  end if;

  -- The claim check. A draft belongs to whoever created it and to nobody else;
  -- there is no transfer path here, deliberately. If a second account could name
  -- someone else's draft ID, this is what stops it.
  --
  -- Deliberately not audited here. An audit row written in this transaction is
  -- rolled back by the RAISE on the next line -- Postgres has no autonomous
  -- transactions -- so the insert would be dead code that looks like a control.
  -- Denials are recorded by the advisory checks, which commit. See
  -- can_publish_job().
  if v_job.customer_id <> v_uid then
    raise exception 'This job belongs to another account' using errcode = '42501';
  end if;

  v_old_quote := v_job.price_quote_id;

  -- Re-validate the quote against today's rules. A price locked before an
  -- upgrade may have been locked under a superseded rule set, or simply be old
  -- enough to have gone stale — publishing on a number we would no longer quote
  -- is a promise we did not make.
  --
  -- Note what this does NOT do: it never edits the old quote. price_quotes are
  -- immutable by trigger, so a recalculation locks a new one and the original
  -- survives as the record of what the guest was actually shown.
  if v_job.price_quote_id is not null then
    v_ttl := coalesce(business_rule_int(active_business_rule_set(), 'price_quote_ttl_minutes'), 1440);

    if exists (
      select 1 from price_quotes q
       where q.id = v_job.price_quote_id
         and (q.locked_at <= now() - make_interval(mins => v_ttl)
              or q.pricing_rule_set_id <> active_pricing_rule_set()
              or q.business_rule_set_id <> active_business_rule_set())
    ) then
      v_new_quote := lock_job_price(p_job_id, v_job.diagnosis_id);
      v_changed := v_new_quote is distinct from v_old_quote;
    end if;
  end if;

  select * into v_job from jobs where id = p_job_id;

  return query select
    true,
    v_job.id,
    v_job.price_quote_id,
    v_changed,
    (v_job.price_quote_id is not null and v_job.status in ('priced', 'published'));
end;

