procedure:public.complete_notification(u.source_code:
declare
  v_event notification_outbox%rowtype;
begin
  select * into v_event from notification_outbox where id = p_outbox_id for update;
  if not found then
    raise exception 'Outbox event not found' using errcode = 'no_data_found';
  end if;

  insert into notifications (
    recipient_user_id, event_type, title, body,
    entity_type, entity_id, action_route, priority, outbox_id
  ) values (
    v_event.recipient_user_id, v_event.event_type, p_title, p_body,
    v_event.entity_type, v_event.entity_id,
    v_event.payload ->> 'action_route', v_event.priority, v_event.id
  )
  -- The unique outbox_id makes a replayed completion a no-op rather than a
  -- second row in the user's notification list.
  on conflict (outbox_id) do nothing;

  update notification_outbox
     set status = 'dispatched', dispatched_at = now(), last_error = null, updated_at = now()
   where id = p_outbox_id;
end;

