procedure:public.confirm_booking_phase(u.definition:
CREATE OR REPLACE FUNCTION public.confirm_booking_phase(p_phase_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_booking bookings%rowtype;
  v_phase   booking_phases%rowtype;
begin
  select * into v_phase from booking_phases where id = p_phase_id;
  if not found then
    raise exception 'No such phase' using errcode = 'no_data_found';
  end if;

  select * into v_booking from bookings where id = v_phase.booking_id;

  -- The customer alone. A pro confirming their own phase would make the record
  -- worthless precisely when it matters.
  if v_booking.customer_id is distinct from auth.uid() then
    raise exception 'Only the customer can confirm progress'
      using errcode = '42501';
  end if;

  if v_phase.confirmed_at is not null then
    return;  -- already confirmed; confirming twice is not an error
  end if;

  update booking_phases set confirmed_at = now() where id = p_phase_id;

  insert into notification_outbox (recipient_user_id, event_type, entity_type,
                                   entity_id, event_version, priority, payload)
  values (v_booking.pro_id, 'phase_confirmed', 'booking_phase', p_phase_id, 1, 'normal',
          jsonb_build_object('booking_id', v_phase.booking_id, 'phase_id', p_phase_id))
  on conflict (recipient_user_id, event_type, entity_id, event_version) do nothing;
end;
$function$

procedure:public.customer_confirm_comple.source_code:
declare v_caller uuid := auth.uid(); v_b bookings%rowtype;
begin
  select * into v_b from bookings where id = p_booking_id for update;
  if not found then raise exception 'Booking not found' using errcode = 'no_data_found'; end if;
  if v_b.customer_id <> v_caller then
    raise exception 'Only the customer may confirm completion' using errcode = '42501';
  end if;

  v_b := apply_booking_transition(p_booking_id, 'completed', 'customer', v_caller,
                                  'Customer confirmed completion');

  update booking_completions set confirmed_at = now() where booking_id = p_booking_id;
  update jobs set status = 'completed', updated_at = now() where id = v_b.job_id;

  perform queue_booking_notification(p_booking_id, v_b.pro_id, 'completion_confirmed', 'high');
  return v_b;
end;

