procedure:public.customer_open_dispute(u.source_code:
declare v_caller uuid := auth.uid(); v_b bookings%rowtype; v_d booking_disputes%rowtype;
begin
  select * into v_b from bookings where id = p_booking_id for update;
  if not found then raise exception 'Booking not found' using errcode = 'no_data_found'; end if;
  if v_b.customer_id <> v_caller then
    raise exception 'Only the customer may open a dispute on this booking' using errcode = '42501';
  end if;
  if coalesce(trim(p_summary), '') = '' then
    raise exception 'A dispute needs a description' using errcode = 'invalid_parameter_value';
  end if;

  perform apply_booking_transition(p_booking_id, 'disputed', 'customer', v_caller,
                                   'Dispute opened', jsonb_build_object('category', p_category));

  insert into booking_disputes (booking_id, opened_by, category, summary)
  values (p_booking_id, v_caller, p_category, p_summary)
  on conflict (booking_id) do nothing
  returning * into v_d;

  if v_d.id is null then
    select * into v_d from booking_disputes where booking_id = p_booking_id;
  end if;

  perform queue_booking_notification(p_booking_id, v_b.pro_id, 'dispute_opened', 'critical');
  return v_d;
end;

