procedure:public.deactivate_my_account(t.source_code:
declare
  v_live int;
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;

  select count(*) into v_live
    from bookings b
   where (b.customer_id = auth.uid() or b.pro_id = auth.uid())
     and not booking_is_terminal(b.status);

  if v_live > 0 then
    raise exception
      'You have % booking(s) still in progress. Finish or cancel them first.', v_live
      using errcode = 'invalid_parameter_value', hint = 'live_bookings';
  end if;

  update profiles
     set is_active = false,
         deactivated_at = now()
   where id = auth.uid();

  -- A deactivated pro stops being offered work immediately.
  update pro_profiles
     set is_accepting_work = false
   where profile_id = auth.uid();

  insert into audit_events (actor_id, actor_kind, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'user', 'account.deactivated', 'profile', auth.uid(),
          jsonb_build_object('reason', left(coalesce(p_reason, ''), 500)));
end;

procedure:public.decide_scope_change(uui.source_code:
declare
  v_sc scope_changes%rowtype;
begin
  select * into v_sc from scope_changes where id = p_scope_change_id for update;
  if not found then
    raise exception 'Scope change not found' using errcode = 'no_data_found';
  end if;

  if v_sc.customer_id <> auth.uid() then
    raise exception 'Only the customer for this booking may decide a scope change'
      using errcode = '42501';
  end if;

  -- Idempotent: a double tap, or a retry after a dropped response, returns the
  -- decision already recorded instead of raising or flipping it.
  if v_sc.status in ('approved','rejected') then
    return v_sc.status;
  end if;

  if v_sc.status <> 'submitted' then
    raise exception 'Only a submitted scope change can be decided (status %)',
      v_sc.status using errcode = 'invalid_parameter_value';
  end if;

  if p_approve then
    -- The constraint also enforces this; raising here says why.
    if v_sc.price_quote_id is null then
      raise exception 'A scope change cannot be approved without an engine price'
        using errcode = 'invalid_parameter_value';
    end if;

    update scope_changes
       set status      = 'approved',
           approved_by = auth.uid(),
           approved_at = now(),
           reviewed_at = now(),
           updated_at  = now()
     where id = p_scope_change_id;
  else
    update scope_changes
       set status           = 'rejected',
           rejected_at      = now(),
           reviewed_at      = now(),
           rejection_reason = left(p_reason, 500),
           updated_at       = now()
     where id = p_scope_change_id;
  end if;

  insert into audit_events (actor_id, actor_kind, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'user',
          case when p_approve then 'scope_change.approved' else 'scope_change.rejected' end,
          'scope_change', p_scope_change_id,
          jsonb_build_object('booking_id', v_sc.booking_id,
                             'price_quote_id', v_sc.price_quote_id));

  return (select status from scope_changes where id = p_scope_change_id);
end;

