procedure:public.detach_payment_method_b.source_code:
declare
  v_row payment_methods%rowtype;
begin
  if not is_trusted_caller() then
    raise exception 'Only the server may detach a payment method'
      using errcode = '42501';
  end if;

  select * into v_row from payment_methods
   where stripe_payment_method_id = p_stripe_pm_id;

  if not found then
    return;  -- nothing to do; a detach we never knew about is not an error
  end if;

  update payment_methods
     set detached_at = coalesce(detached_at, now()),
         is_default  = false,
         updated_at  = now()
   where id = v_row.id;

  -- Removing the default leaves the person with none, which would silently
  -- break the next booking. Promote the most recently saved survivor.
  if v_row.is_default then
    update payment_methods
       set is_default = true, updated_at = now()
     where id = (
       select id from payment_methods
        where profile_id = v_row.profile_id
          and detached_at is null
        order by created_at desc
        limit 1
     );
  end if;
end;

procedure:public.diagnose_claim(text,uui.source_code:
declare
  v diagnosis_attempts%rowtype;
begin
  if p_key is null or length(p_key) = 0 then
    raise exception 'An idempotency key is required' using errcode = 'invalid_parameter_value';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_key, 0));

  select * into v from diagnosis_attempts where idempotency_key = p_key for update;

  if not found then
    insert into diagnosis_attempts
      (idempotency_key, customer_id, job_id, request_fingerprint,
       state, claim_expires_at)
    values
      (p_key, p_customer_id, p_job_id, p_fingerprint,
       'in_progress', now() + make_interval(secs => p_ttl_seconds));

    return query select 'proceed'::text, null::uuid, null::uuid, null::text, 1;
    return;
  end if;

  -- Same key, different request. Returning the earlier answer here would hand
  -- one customer another customer's diagnosis, or answer a question that was
  -- never asked. Refused, and deliberately not treated as a replay.
  if v.customer_id is distinct from p_customer_id
     or v.job_id is distinct from p_job_id
     or v.request_fingerprint is distinct from p_fingerprint then
    return query select 'mismatch'::text, null::uuid, null::uuid, null::text, v.attempts;
    return;
  end if;

  if v.state = 'succeeded' then
    return query select 'replay'::text, v.diagnosis_id, v.price_quote_id,
                        v.outcome_kind, v.attempts;
    return;
  end if;

  -- A live claim held by somebody else.
  if v.state in ('in_progress', 'diagnosed') and v.claim_expires_at > now() then
    return query select 'in_progress'::text, null::uuid, null::uuid, null::text, v.attempts;
    return;
  end if;

  -- Failed, or the previous holder died and its claim lapsed. Take it over,
  -- keeping any diagnosis it already paid for.
  update diagnosis_attempts
     set state            = case when v.diagnosis_id is not null
                                 then 'diagnosed'::diagnosis_attempt_state
                                 else 'in_progress'::diagnosis_attempt_state end,
         attempts         = v.attempts + 1,
         claim_expires_at = now() + make_interval(secs => p_ttl_seconds),
         last_error       = null,
         updated_at       = now()
   where idempotency_key = p_key;

  return query select
    case when v.diagnosis_id is not null then 'resume' else 'proceed' end::text,
    v.diagnosis_id, null::uuid, null::text, v.attempts + 1;
end;

