procedure:public.diagnose_succeed(text,t.source_code:
declare
  v diagnosis_attempts%rowtype;
begin
  select * into v from diagnosis_attempts where idempotency_key = p_key for update;
  if not found then
    raise exception 'No attempt for this key' using errcode = 'no_data_found';
  end if;

  if p_outcome_kind = 'priced' then
    if p_price_quote_id is null then
      raise exception 'A priced outcome must carry a price quote'
        using errcode = 'invalid_parameter_value';
    end if;

    if not exists (
      select 1 from jobs j
       where j.id = v.job_id and j.price_quote_id = p_price_quote_id
    ) then
      raise exception 'Price quote % is not the locked quote for job %',
        p_price_quote_id, v.job_id using errcode = 'invalid_parameter_value';
    end if;
  elsif p_price_quote_id is not null then
    raise exception 'Outcome % must not carry a price quote', p_outcome_kind
      using errcode = 'invalid_parameter_value';
  end if;

  update diagnosis_attempts
     set state          = 'succeeded',
         outcome_kind   = p_outcome_kind,
         price_quote_id = p_price_quote_id,
         completed_at   = now(),
         last_error     = null,
         updated_at     = now()
   where idempotency_key = p_key;
end;

