AS $function$
declare
  v_prs     uuid := active_pricing_rule_set();
  v_brs     uuid := active_business_rule_set();
  v_rules   category_pricing_rules%rowtype;
  v_comm    int;
  v_fee_bp  bigint;
  v_pay     bigint;
  v_labour  bigint;
begin
  if p_rate_cents is null or p_rate_cents <= 0 then return null; end if;
  if v_prs is null or v_brs is null then return null; end if;

  select * into v_rules from category_pricing_rules
   where rule_set_id = v_prs and category_id = p_category_id;
  if not found then return null; end if;

  v_comm := coalesce(business_rule_int(v_brs, 'platform_commission_bp'), 1000);
  -- Same guard as the booking snapshot: at 10000 the gross-up divides by zero.
  if v_comm < 0 or v_comm >= 10000 then return null; end if;

  v_fee_bp := coalesce(business_rule_int(v_brs, 'customer_fee_bp'), 1500);

  v_pay := p_rate_cents
         + (p_rate_cents * case p_priority
              when 'soon'   then v_rules.soon_adjustment_bp
              when 'urgent' then v_rules.urgent_adjustment_bp
              else 0 end) / 10000;

  v_labour := (v_pay * 10000) / (10000 - v_comm);
  return v_labour + (v_labour * v_fee_bp) / 10000;
end;
$function$

procedure:public.expire_unconfirmed_book.source_code:
declare r record; n int := 0;
begin
  for r in
    select id from bookings
    where status = 'pending_pro_confirmation'
      and decline_deadline is not null
      and decline_deadline < now()
    for update skip locked
  loop
    perform apply_booking_transition(r.id, 'expired', 'system', null,
                                     'Pro did not confirm in time');
    perform release_booking_and_reopen_job(r.id, 'expired', 'Confirmation deadline passed');
    n := n + 1;
  end loop;
  return n;
end;

