procedure:public.fail_notification(uuid,.source_code:
declare
  v_attempts int;
begin
  select attempts into v_attempts from notification_outbox where id = p_outbox_id;
  if v_attempts is null then
    raise exception 'Outbox event not found' using errcode = 'no_data_found';
  end if;

  update notification_outbox
     set status = case when v_attempts >= p_max_attempts then 'failed'::outbox_status
                       else 'pending'::outbox_status end,
         last_error = left(coalesce(p_error, ''), 500),
         -- 2s, 4s, 8s, 16s, 32s.
         available_at = now() + make_interval(secs => power(2, least(v_attempts, 6))::int),
         updated_at = now()
   where id = p_outbox_id;
end;

