procedure:public.fail_outbox_event(uuid,.source_code:
declare
  v_attempts int;
begin
  if not is_trusted_context() then
    raise exception 'Only the dispatcher may fail notifications'
      using errcode = '42501';
  end if;

  select attempts into v_attempts from notification_outbox where id = p_id;
  if not found then
    raise exception 'No such outbox event' using errcode = 'no_data_found';
  end if;

  update notification_outbox
     set status = case when v_attempts >= p_max_attempts then 'failed'::outbox_status
                       else 'pending'::outbox_status end,
         -- 1m, 2m, 4m, 8m … capped. Truncated to whole minutes so the backoff
         -- is legible in the table rather than a stream of odd intervals.
         available_at = now() + make_interval(mins => least(power(2, v_attempts)::int, 60)),
         -- Bounded, and it is an error string from our own dispatcher, never a
         -- provider payload — which could carry a token.
         last_error = left(coalesce(p_error, 'unknown'), 500),
         updated_at = now()
   where id = p_id;
end;

