procedure:public.jobs_limit_guest_drafts.source_code:
declare
  v_anonymous boolean;
  v_max int;
  v_count int;
begin
  select p.is_anonymous into v_anonymous from profiles p where p.id = new.customer_id;
  if not coalesce(v_anonymous, false) then
    return new;
  end if;

  v_max := coalesce(business_rule_int(active_business_rule_set(), 'guest_max_active_drafts'), 2);

  perform pg_advisory_xact_lock(hashtextextended('guest_drafts:' || new.customer_id::text, 0));

  select count(*) into v_count
    from jobs
   where customer_id = new.customer_id
     and status in ('draft', 'pending_diagnosis', 'priced')
     and id <> new.id;

  if v_count >= v_max then
    raise exception 'You can work on % jobs at a time. Finish or discard one first.', v_max
      using errcode = 'check_violation', hint = 'guest_draft_limit';
  end if;

  return new;
end;

