  select p.is_anonymous into v_anonymous from profiles p where p.id = new.customer_id;

  if coalesce(v_anonymous, false) then
    v_ttl := coalesce(business_rule_int(active_business_rule_set(), 'guest_draft_ttl_hours'), 48);
    new.guest_expires_at := coalesce(new.guest_expires_at, now() + make_interval(hours => v_ttl));
