procedure:public.link_stripe_customer(uu.source_code:
begin
  if not is_trusted_caller() then
    raise exception 'Only the server may link a Stripe customer'
      using errcode = '42501';
  end if;

  if p_stripe_customer_id is null or p_stripe_customer_id !~ '^cus_' then
    raise exception 'That is not a Stripe customer id'
      using errcode = 'invalid_parameter_value', hint = 'bad_customer_id';
  end if;

  -- Re-linking is allowed and idempotent, but REPOINTING is not: a profile that
  -- already maps to one Stripe customer must never be silently moved to
  -- another, because the saved cards would come with it.
  insert into stripe_customers (profile_id, stripe_customer_id, livemode)
  values (p_profile_id, p_stripe_customer_id, coalesce(p_livemode, false))
  on conflict (profile_id) do update
     set updated_at = now()
   where stripe_customers.stripe_customer_id = excluded.stripe_customer_id;

  if not found then
    raise exception 'That profile is already linked to a different Stripe customer'
      using errcode = 'unique_violation', hint = 'already_linked';
  end if;
end;

procedure:public.lock_job_price(uuid,uui.source_code:
declare
  v_job         jobs%rowtype;
  v_diag        diagnoses%rowtype;
  v_rules       category_pricing_rules%rowtype;
  v_prs         uuid := active_pricing_rule_set();
  v_brs         uuid := active_business_rule_set();
  v_minutes     int;
  v_complexity_bp int;
  v_priority_bp int := 0;
  v_base        bigint;
  v_labor       bigint;
  v_fee_bp      bigint;
  v_comm_bp     bigint;
  v_fee         bigint;
  v_commission  bigint;
  v_quote_id    uuid;
begin
  if v_prs is null or v_brs is null then
    raise exception 'No active pricing or business rule set' using errcode = 'invalid_parameter_value';
  end if;

  select * into v_job from jobs where id = p_job_id for update;
  if not found then
    raise exception 'Job not found' using errcode = 'no_data_found';
  end if;

  -- Re-pricing a published job would break the promise that the price is locked.
  if v_job.price_quote_id is not null and v_job.status not in ('draft','pending_diagnosis') then
    raise exception 'Job % already carries a locked price', p_job_id using errcode = 'invalid_parameter_value';
  end if;

  -- A dangerous situation is not a job to be priced.
  if v_job.safety_classification = 'emergency_redirect' then
    raise exception 'An emergency-redirect job cannot be priced' using errcode = 'invalid_parameter_value';
  end if;

  select * into v_rules
  from category_pricing_rules
  where rule_set_id = v_prs and category_id = v_job.category_id;
  if not found then
    raise exception 'No pricing rule for category % in rule set %', v_job.category_id, v_prs
      using errcode = 'no_data_found';
  end if;

  if p_diagnosis_id is not null then
    select * into v_diag from diagnoses where id = p_diagnosis_id;
  end if;

  -- Duration: the diagnosis advises, the rule set sets the floor.
  v_minutes := greatest(
    coalesce(v_diag.estimated_duration_minutes, v_job.estimated_duration_minutes),
    v_rules.minimum_duration_minutes
  );

  v_complexity_bp := case coalesce(v_diag.complexity, 'medium')
    when 'low'  then v_rules.complexity_low_bp
    when 'high' then v_rules.complexity_high_bp
    else v_rules.complexity_medium_bp
  end;

  -- The priority uplift is a rule, never a number the model invented.
  v_priority_bp := case v_job.final_priority
    when 'soon'   then v_rules.soon_adjustment_bp
    when 'urgent' then v_rules.urgent_adjustment_bp
    else 0
  end;

  v_base  := (v_rules.base_rate_cents_per_hour * v_minutes) / 60;
  v_labor := (v_base * v_complexity_bp) / 10000;
  v_labor := v_labor + (v_labor * v_priority_bp) / 10000;
  v_labor := greatest(v_labor, v_rules.minimum_charge_cents);

  v_fee_bp  := coalesce(business_rule_int(v_brs, 'customer_fee_bp'), 1500);
  v_comm_bp := coalesce(business_rule_int(v_brs, 'platform_commission_bp'), 1000);

  v_fee        := (v_labor * v_fee_bp)  / 10000;
  v_commission := (v_labor * v_comm_bp) / 10000;

  insert into price_quotes (
    diagnosis_id, category_id, priority,
    pricing_rule_set_id, business_rule_set_id,
    billable_minutes, calculation,
    labor_amount_cents, customer_fee_cents,
    platform_commission_cents, expected_payout_cents
  ) values (
    p_diagnosis_id, v_job.category_id, v_job.final_priority,
    v_prs, v_brs,
    v_minutes,
    jsonb_build_object(
      'base_rate_cents_per_hour', v_rules.base_rate_cents_per_hour,
      'billable_minutes',         v_minutes,
      'minimum_duration_minutes', v_rules.minimum_duration_minutes,
      'base_cents',               v_base,
      'complexity',               coalesce(v_diag.complexity, 'medium'),
      'complexity_bp',            v_complexity_bp,
      'priority',                 v_job.final_priority,
      'priority_adjustment_bp',   v_priority_bp,
      'minimum_charge_cents',     v_rules.minimum_charge_cents,
      'customer_fee_bp',          v_fee_bp,
      'platform_commission_bp',   v_comm_bp
    ),
    v_labor, v_fee, v_commission, v_labor - v_commission
  )
  returning id into v_quote_id;

  update jobs
     set price_quote_id = v_quote_id,
         diagnosis_id   = coalesce(p_diagnosis_id, diagnosis_id),
         estimated_duration_minutes = v_minutes,
         status         = 'priced',
         updated_at     = now()
   where id = p_job_id;

  insert into audit_events (actor_id, actor_kind, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'system', 'price.locked', 'job', p_job_id,
          jsonb_build_object('quote_id', v_quote_id, 'pricing_rule_set_id', v_prs,
                             'labor_amount_cents', v_labor));

  return v_quote_id;
end;

procedure:public.lock_job_price(uuid,uui.definition:
CREATE OR REPLACE FUNCTION public.lock_job_price(p_job_id uuid, p_diagnosis_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_job         jobs%rowtype;
  v_diag        diagnoses%rowtype;
  v_rules       category_pricing_rules%rowtype;
  v_prs         uuid := active_pricing_rule_set();
  v_brs         uuid := active_business_rule_set();
  v_minutes     int;
  v_complexity_bp int;
  v_priority_bp int := 0;
  v_base        bigint;
  v_labor       bigint;
  v_fee_bp      bigint;
  v_comm_bp     bigint;
  v_fee         bigint;
  v_commission  bigint;
  v_quote_id    uuid;
begin
  if v_prs is null or v_brs is null then
    raise exception 'No active pricing or business rule set' using errcode = 'invalid_parameter_value';
  end if;

  select * into v_job from jobs where id = p_job_id for update;
  if not found then
    raise exception 'Job not found' using errcode = 'no_data_found';
  end if;

  -- Re-pricing a published job would break the promise that the price is locked.
  if v_job.price_quote_id is not null and v_job.status not in ('draft','pending_diagnosis') then
    raise exception 'Job % already carries a locked price', p_job_id using errcode = 'invalid_parameter_value';
  end if;

  -- A dangerous situation is not a job to be priced.
  if v_job.safety_classification = 'emergency_redirect' then
    raise exception 'An emergency-redirect job cannot be priced' using errcode = 'invalid_parameter_value';
  end if;

  select * into v_rules
  from category_pricing_rules
  where rule_set_id = v_prs and category_id = v_job.category_id;
  if not found then
    raise exception 'No pricing rule for category % in rule set %', v_job.category_id, v_prs
      using errcode = 'no_data_found';
  end if;

  if p_diagnosis_id is not null then
    select * into v_diag from diagnoses where id = p_diagnosis_id;
  end if;

  -- Duration: the diagnosis advises, the rule set sets the floor.
  v_minutes := greatest(
    coalesce(v_diag.estimated_duration_minutes, v_job.estimated_duration_minutes),
    v_rules.minimum_duration_minutes
  );

  v_complexity_bp := case coalesce(v_diag.complexity, 'medium')
    when 'low'  then v_rules.complexity_low_bp
    when 'high' then v_rules.complexity_high_bp
    else v_rules.complexity_medium_bp
  end;

  -- The priority uplift is a rule, never a number the model invented.
  v_priority_bp := case v_job.final_priority
    when 'soon'   then v_rules.soon_adjustment_bp
    when 'urgent' then v_rules.urgent_adjustment_bp
    else 0
  end;

  v_base  := (v_rules.base_rate_cents_per_hour * v_minutes) / 60;
  v_labor := (v_base * v_complexity_bp) / 10000;
  v_labor := v_labor + (v_labor * v_priority_bp) / 10000;
  v_labor := greatest(v_labor, v_rules.minimum_charge_cents);

  v_fee_bp  := coalesce(business_rule_int(v_brs, 'customer_fee_bp'), 1500);
  v_comm_bp := coalesce(business_rule_int(v_brs, 'platform_commission_bp'), 1000);

  v_fee        := (v_labor * v_fee_bp)  / 10000;
  v_commission := (v_labor * v_comm_bp) / 10000;

  insert into price_quotes (
    diagnosis_id, category_id, priority,
    pricing_rule_set_id, business_rule_set_id,
    billable_minutes, calculation,
    labor_amount_cents, customer_fee_cents,
    platform_commission_cents, expected_payout_cents
  ) values (
    p_diagnosis_id, v_job.category_id, v_job.final_priority,
    v_prs, v_brs,
    v_minutes,
    jsonb_build_object(
      'base_rate_cents_per_hour', v_rules.base_rate_cents_per_hour,
      'billable_minutes',         v_minutes,
      'minimum_duration_minutes', v_rules.minimum_duration_minutes,
      'base_cents',               v_base,
      'complexity',               coalesce(v_diag.complexity, 'medium'),
      'complexity_bp',            v_complexity_bp,
      'priority',                 v_job.final_priority,
      'priority_adjustment_bp',   v_priority_bp,
      'minimum_charge_cents',     v_rules.minimum_charge_cents,
      'customer_fee_bp',          v_fee_bp,
      'platform_commission_bp',   v_comm_bp
    ),
    v_labor, v_fee, v_commission, v_labor - v_commission
  )
  returning id into v_quote_id;

  update jobs
     set price_quote_id = v_quote_id,
         diagnosis_id   = coalesce(p_diagnosis_id, diagnosis_id),
         estimated_duration_minutes = v_minutes,
         status         = 'priced',
         updated_at     = now()
   where id = p_job_id;

  insert into audit_events (actor_id, actor_kind, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'system', 'price.locked', 'job', p_job_id,
          jsonb_build_object('quote_id', v_quote_id, 'pricing_rule_set_id', v_prs,
                             'labor_amount_cents', v_labor));

  return v_quote_id;
end;
$function$

procedure:public.mark_conversation_read(.source_code:
declare
  v_booking bookings%rowtype;
begin
  select b.* into v_booking
    from conversations c join bookings b on b.id = c.booking_id
   where c.id = p_conversation_id;

  if not found then
    raise exception 'No such conversation' using errcode = 'no_data_found';
