  if v_booking.customer_id = auth.uid() then
    update conversations set customer_last_read_at = now() where id = p_conversation_id;
  elsif v_booking.pro_id = auth.uid() then
    update conversations set pro_last_read_at = now() where id = p_conversation_id;
  else
    raise exception 'Only the customer and the assigned pro can read this conversation'
      using errcode = '42501';
  end if;
end;

