procedure:public.material_requests_clamp.source_code:
declare
  v_eligible_sum bigint;
begin
  if new.supply_method = 'customer_provided' then
    new.eligible_reimbursement_cents := 0;
    return new;
  end if;

  select coalesce(sum(line_total_cents), 0) into v_eligible_sum
  from material_line_items
  where request_id = new.id and eligibility = 'eligible';

  -- Whatever the caller supplied is discarded. The reimbursable amount is the
  -- eligible receipt total, capped by the approved maximum and by the receipt.
  new.eligible_reimbursement_cents := least(
    v_eligible_sum,
    coalesce(new.approved_maximum_cents, v_eligible_sum),
    coalesce(new.receipt_total_cents,    v_eligible_sum)
  );
  return new;
end;

