procedure:public.material_requests_role_.source_code:
begin
  if is_trusted_context() or is_admin() then
    return new;
  end if;

  if auth.uid() = old.pro_id then
    -- The pro supplies evidence. Approval fields are not theirs to touch.
    new.approved_by             := old.approved_by;
    new.approved_at             := old.approved_at;
    new.approved_maximum_cents  := old.approved_maximum_cents;
    new.rejected_at             := old.rejected_at;
    new.rejection_reason        := old.rejection_reason;
    new.reimbursed_at           := old.reimbursed_at;
    if new.status in ('approved','rejected','reimbursement_approved','reimbursed') then
      raise exception 'A pro cannot move a material request to %', new.status
        using errcode = '42501';
    end if;

  elsif auth.uid() = old.customer_id then
    -- The customer approves or rejects. They do not author the claim.
    new.receipt_subtotal_cents     := old.receipt_subtotal_cents;
    new.receipt_tax_included_cents := old.receipt_tax_included_cents;
    new.receipt_total_cents        := old.receipt_total_cents;
    new.receipt_path               := old.receipt_path;
    new.estimated_subtotal_cents   := old.estimated_subtotal_cents;
    new.estimated_total_cents      := old.estimated_total_cents;
    new.supply_method              := old.supply_method;
    if new.status not in ('approved','rejected','cancelled', old.status) then
      raise exception 'A customer cannot move a material request to %', new.status
        using errcode = '42501';
    end if;
  end if;
  return new;
end;

