procedure:public.my_referral_code().source_code:
declare
  v_code text;
  v_try  text;
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;

  select referral_code into v_code from profiles where id = auth.uid();
  if v_code is not null then return v_code; end if;

  -- Unambiguous alphabet: no O/0, no I/1/L. A code is read aloud and typed by
  -- somebody else, and the cost of a collision is a wrong attribution.
  for i in 1..12 loop
    v_try := (select string_agg(substr('ABCDEFGHJKMNPQRSTUVWXYZ23456789',
                       (random() * 30)::int + 1, 1), '')
                from generate_series(1, 7));
    begin
      update profiles set referral_code = v_try where id = auth.uid();
      return v_try;
    exception when unique_violation then
      -- Try again with a different code.
    end;
  end loop;

  raise exception 'Could not allocate a referral code, please try again'
    using errcode = 'internal_error';
end;

