procedure:public.open_conversation(uuid).source_code:
declare
  v_id uuid;
begin
  if not is_booking_party(p_booking_id) then
    raise exception 'Only the customer and the assigned pro can open this conversation'
      using errcode = '42501';
  end if;

  -- Get-or-create, concurrency-safe. Two devices opening the screen at the same
  -- instant must not produce two conversations; the unique constraint decides
  -- and the loser reads the winner's row.
  insert into conversations (booking_id) values (p_booking_id)
  on conflict (booking_id) do nothing
  returning id into v_id;

  if v_id is null then
    select id into v_id from conversations where booking_id = p_booking_id;
  end if;

  return v_id;
end;

