  v_b      bookings%rowtype;
begin
  if v_caller is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select * into v_b from bookings where id = p_booking_id for update;
  if not found then raise exception 'Booking not found' using errcode = 'no_data_found'; end if;
  if v_b.pro_id <> v_caller then
    raise exception 'Only the selected pro may confirm this booking' using errcode = '42501';
  end if;
  -- A missed deadline is a decision already made; confirming afterwards would
  -- resurrect a booking the customer has been told is dead.
  if v_b.decline_deadline is not null and v_b.decline_deadline < now()
     and v_b.status = 'pending_pro_confirmation' then
    raise exception 'The confirmation window for this booking has passed'
      using errcode = 'invalid_parameter_value';
  end if;

  v_b := apply_booking_transition(p_booking_id, 'confirmed', 'pro', v_caller, 'Pro confirmed');

  update selection_attempts
     set outcome = 'confirmed', resolved_at = now()
   where booking_id = p_booking_id and outcome = 'pending';

  update jobs set status = 'assigned', updated_at = now() where id = v_b.job_id;

  perform queue_booking_notification(p_booking_id, v_b.customer_id, 'booking_confirmed', 'high');
  return v_b;
end;

