procedure:public.pro_is_available(uuid,t.source_code:
declare
  s          pro_scheduling_settings%rowtype;
  v_block    tstzrange;
  v_jobs_that_day int;
begin
  select * into s from pro_scheduling_settings where pro_id = p_pro_id;
  if not found then
    -- No settings row: fall back to permissive defaults so an existing pro is not
    -- silently excluded before they have configured anything.
    s.travel_buffer_minutes  := 30;
    s.cleanup_buffer_minutes := 15;
    s.min_notice_minutes     := 120;
    s.is_paused              := false;
    s.accepts_standard := true; s.accepts_soon := true;
    s.accepts_urgent := false;  s.max_jobs_per_day := null;
  end if;

  if s.is_paused and (s.paused_until is null or s.paused_until > now()) then
    return false;
  end if;

  if (p_priority = 'standard' and not s.accepts_standard)
     or (p_priority = 'soon'   and not s.accepts_soon)
     or (p_priority = 'urgent' and not s.accepts_urgent) then
    return false;
  end if;

  if p_start < now() + make_interval(mins => s.min_notice_minutes) then
    -- An active Available Now session overrides minimum notice for urgent work.
    if not (p_priority = 'urgent' and pro_is_available_now(p_pro_id, 'urgent')) then
      return false;
    end if;
  end if;

  v_block := tstzrange(
    p_start - make_interval(mins => s.travel_buffer_minutes),
    p_start + make_interval(mins => p_duration_minutes + s.cleanup_buffer_minutes + s.travel_buffer_minutes),
    '[)'
  );

  -- The whole block must sit inside ONE open window. Starting inside working
  -- hours is not sufficient — the job has to finish inside them too.
  if not exists (
    select 1 from pro_open_windows(p_pro_id, lower(v_block), upper(v_block), p_priority) w
    where w.window_range @> v_block
  ) then
    return false;
  end if;

  if exists (
    select 1 from pro_time_blocks b
    where b.pro_id = p_pro_id
      and b.time_range && v_block
      and (b.expires_at is null or b.expires_at > now())
  ) then
    return false;
  end if;

  if s.max_jobs_per_day is not null then
    select count(*) into v_jobs_that_day
    from bookings bk
    where bk.pro_id = p_pro_id
      and bk.status in ('pending_pro_confirmation','confirmed','in_progress')
      and bk.scheduled_start::date = p_start::date;
    if v_jobs_that_day >= s.max_jobs_per_day then
      return false;
    end if;
  end if;

  return true;
end;

