begin
  if is_trusted_context() or is_admin() then
    return new;
  end if;

  -- Approval is a human decision recorded by Tarea, never a value supplied by
  -- the applicant. 'not_started' is the column default and the honest initial
  -- state for a row the applicant just created.
  new.approval_state        := 'not_started';
  new.approved_at           := null;
  new.suspended_at          := null;
  new.suspension_reason     := null;

  -- Payout readiness comes from Stripe via an authenticated webhook or a
  -- verified API response. It is never asserted by the pro.
  new.payouts_enabled       := false;
  new.stripe_account_id     := null;
  new.stripe_account_state  := null;

  -- Reputation is earned, not declared.
  new.rating_average        := null;
  new.rating_count          := 0;
  new.completed_jobs_count  := 0;

  return new;
end;

