declare v_caller uuid := auth.uid(); v_b bookings%rowtype;
begin
  select * into v_b from bookings where id = p_booking_id for update;
  if not found then raise exception 'Booking not found' using errcode = 'no_data_found'; end if;
  if v_b.pro_id <> v_caller then
    raise exception 'Only the assigned pro may submit completion' using errcode = '42501';
  end if;

  v_b := apply_booking_transition(
    p_booking_id, 'completion_submitted', 'pro', v_caller, 'Completion submitted',
    jsonb_build_object('evidence_count', coalesce(array_length(p_evidence_paths, 1), 0))
  );

  insert into booking_completions (booking_id, submitted_by, notes, evidence_paths)
  values (p_booking_id, v_caller, p_notes, p_evidence_paths)
  on conflict (booking_id) do update
    set notes = excluded.notes, evidence_paths = excluded.evidence_paths;

  -- Deliberately does NOT complete the booking or release any payout. The
  -- customer confirms, and payout belongs to the payment unit.
  perform queue_booking_notification(p_booking_id, v_b.customer_id, 'completion_submitted', 'high');
  return v_b;
end;

