procedure:public.rate_limit_acquire_leas.source_code:
declare
  v_ids    uuid[] := '{}';
  v_id     uuid;
  v_scope  rate_limit_scope;
  v_hash   bytea;
  v_max    int;
  v_active int;
begin
  -- Deterministic order — device before ip — so two requests sharing both
  -- subjects cannot take the locks in opposite orders and deadlock.
  foreach v_scope in array array['device'::rate_limit_scope, 'ip'::rate_limit_scope] loop
    v_hash := case v_scope when 'device' then p_device_hash else p_ip_hash end;
    continue when v_hash is null;

    select max_concurrent into v_max
      from rate_limit_policies
     where action = p_action and scope = v_scope and subject_class = p_subject_class;

    -- No policy, or an unmetered one. Nothing to acquire for this scope, and
    -- explicitly NOT a refusal.
    continue when v_max is null;

    perform rate_limit_lock(p_action, v_scope, v_hash);

    delete from rate_limit_leases
     where action = p_action and scope = v_scope and expires_at <= now();

    select count(*) into v_active
      from rate_limit_leases
     where action = p_action and scope = v_scope and subject_hash = v_hash
       and expires_at > now();

    if v_active >= v_max then
      -- Refused. Give back anything already taken for the other scope so a
      -- rejected request leaves no slot held against the customer, and return
      -- NULL — the value that means "do not proceed".
      delete from rate_limit_leases where id = any(v_ids);
      return null;
    end if;

    insert into rate_limit_leases (action, scope, subject_hash, expires_at)
    values (p_action, v_scope, v_hash, now() + make_interval(secs => p_ttl_seconds))
    returning id into v_id;

    v_ids := v_ids || v_id;
  end loop;

  -- Possibly empty, and that is fine: it means no scope needed metering.
  return v_ids;
end;

