procedure:public.rate_limit_evaluate(tex.source_code:
declare
  v_device rate_limit_decision;
  v_ip     rate_limit_decision;
  v_user   rate_limit_decision;
  v_worst  rate_limit_decision;
  v_fails  int;
begin
  v_device := rate_limit_evaluate_scope(p_action, 'device', p_subject_class, p_device_hash, p_profile_id);
  v_ip     := rate_limit_evaluate_scope(p_action, 'ip',     p_subject_class, p_ip_hash,     p_profile_id);
  v_user   := rate_limit_evaluate_scope(p_action, 'user',   p_subject_class, p_user_hash,   p_profile_id);

  -- Shared-IP handling, in both directions.
  --
  -- Written as one block over the whole non-allow range rather than as a test
  -- for 'deny' alone: the configured on_exceed for an IP scope is already
  -- 'challenge', so a rule that only fired on 'deny' would never see the case
  -- it was written for, and repeated challenge failures could never escalate.
  if v_ip.outcome <> 'allow' then
    select count(*) into v_fails
      from rate_limit_challenges
     where subject_hash = p_device_hash
       and action = p_action
       and not passed
       and created_at > now() - interval '1 hour';

    if coalesce(v_fails, 0) >= 3 then
      -- A device that has failed three challenges in an hour is not a coworking
      -- space. The benefit of the doubt is spent.
      v_ip.outcome := 'deny';
      v_ip.retry_after_seconds := greatest(v_ip.retry_after_seconds, 3600);
    elsif v_device.outcome = 'allow' then
      -- The device itself is behaving. The IP alone is a risk signal, not proof
      -- of abuse, so this is a challenge and never a block.
      v_ip.outcome := 'challenge';
      v_ip.retry_after_seconds := 0;
    end if;
  end if;

  v_worst := v_device;
  if v_ip.outcome   > v_worst.outcome then v_worst := v_ip;   end if;
  if v_user.outcome > v_worst.outcome then v_worst := v_user; end if;

  -- Report the tightest remaining allowance regardless of which scope decided.
  v_worst.remaining := least(
    coalesce(v_device.remaining, 2147483647),
    coalesce(v_ip.remaining,     2147483647),
    coalesce(v_user.remaining,   2147483647)
  );

  return v_worst;
end;

