procedure:public.rate_limit_evaluate_sco.source_code:
declare
  v_pol      rate_limit_policies%rowtype;
  v_max      int;
  v_window   int;
  v_conc     int;
  v_used     int;
  v_last     timestamptz;
  v_burst    int;
  v_active   int;
  v_ovr_max     int;
  v_ovr_window  int;
  v_ovr_conc    int;
  v_result   rate_limit_decision;
begin
  v_result := row('allow', 0, p_scope, null)::rate_limit_decision;

  if p_hash is null then
    return v_result;
  end if;

  select * into v_pol from rate_limit_policies
   where action = p_action and scope = p_scope and subject_class = p_subject_class;
  if not found then
    return v_result;   -- unconfigured scope is unmetered, by construction
  end if;

  v_max    := v_pol.max_events;
  v_window := v_pol.window_seconds;
  v_conc   := v_pol.max_concurrent;

  -- A live support override replaces the numbers for this account only.
  --
  -- Assigned through a found-guard rather than straight into the limit
  -- variables: in plpgsql a SELECT INTO that matches no row sets its targets to
  -- NULL, and NULL max_events means *unmetered* here. Writing this the obvious
  -- way made every account without an override — which is nearly all of them —
  -- unlimited, and made an expired override strictly more permissive than a
  -- live one.
  if p_profile_id is not null then
    select o.max_events, o.window_seconds, o.max_concurrent
      into v_ovr_max, v_ovr_window, v_ovr_conc
      from rate_limit_overrides o
     where o.profile_id = p_profile_id
       and o.action = p_action
       and (o.expires_at is null or o.expires_at > now());

    if found then
      v_max    := coalesce(v_ovr_max,    v_max);
      v_window := coalesce(v_ovr_window, v_window);
      v_conc   := coalesce(v_ovr_conc,   v_conc);
    end if;
  end if;

  perform rate_limit_lock(p_action, p_scope, p_hash);

  select count(*), max(occurred_at)
    into v_used, v_last
    from rate_limit_events
   where action = p_action and scope = p_scope and subject_hash = p_hash
     and occurred_at > now() - make_interval(secs => v_window);

  v_result.remaining := case when v_max is null then null
                             else greatest(v_max - v_used, 0) end;

  -- Bursts are machinery. Checked before the allowance, and always a hard deny:
  -- a client that fires twenty requests in ten seconds is not a person who
  -- needs a CAPTCHA, and offering one would just be a puzzle for a script.
  if v_pol.burst_events is not null then
    select count(*) into v_burst
      from rate_limit_events
     where action = p_action and scope = p_scope and subject_hash = p_hash
       and occurred_at > now() - make_interval(secs => v_pol.burst_window_seconds);

    if v_burst >= v_pol.burst_events then
      return row('deny', v_pol.burst_window_seconds, p_scope, 0)::rate_limit_decision;
    end if;
  end if;

  -- Concurrency. Expired leases are swept first so a crashed request does not
  -- hold a slot until someone notices.
  if v_conc is not null then
    delete from rate_limit_leases
     where action = p_action and scope = p_scope and expires_at <= now();

    select count(*) into v_active
      from rate_limit_leases
     where action = p_action and scope = p_scope and subject_hash = p_hash
       and expires_at > now();

    if v_active >= v_conc then
      return row('deny', 30, p_scope, v_result.remaining)::rate_limit_decision;
    end if;
  end if;

  -- Minimum interval between operations.
  if v_pol.min_interval_seconds > 0 and v_last is not null then
    if v_last > now() - make_interval(secs => v_pol.min_interval_seconds) then
      return row(
        'deny',
        greatest(
          ceil(extract(epoch from
            (v_last + make_interval(secs => v_pol.min_interval_seconds)) - now()))::int,
          1),
        p_scope,
        v_result.remaining
      )::rate_limit_decision;
    end if;
  end if;

  -- The allowance itself. What exceeding it means comes from the policy.
  if v_max is not null and v_used >= v_max then
    v_result.outcome := v_pol.on_exceed;
    v_result.retry_after_seconds := case
      when v_pol.on_exceed = 'deny' then
        greatest(
          ceil(extract(epoch from (
            select min(occurred_at) from rate_limit_events
             where action = p_action and scope = p_scope and subject_hash = p_hash
               and occurred_at > now() - make_interval(secs => v_window)
          ) + make_interval(secs => v_window) - now()))::int, 1)
      else 0
    end;
    v_result.remaining := 0;
  end if;

  return v_result;
end;

