procedure:public.rate_limit_record(text,.source_code:
begin
  insert into rate_limit_events (action, scope, subject_hash)
  select p_action, s.scope, s.hash
    from (values ('device'::rate_limit_scope, p_device_hash),
                 ('ip'::rate_limit_scope,     p_ip_hash),
                 ('user'::rate_limit_scope,   p_user_hash)) as s(scope, hash)
