procedure:public.reply_to_review(uuid,te.source_code:
declare
  v_review reviews%rowtype;
  v_reply  text;
begin
  select * into v_review from reviews where id = p_review_id;
  if not found then
    raise exception 'No such review' using errcode = 'no_data_found';
  end if;

  if v_review.reviewee_id is distinct from auth.uid() then
    raise exception 'Only the pro who was reviewed can reply'
      using errcode = '42501';
  end if;

  if v_review.reply is not null then
    raise exception 'You have already replied to this review'
      using errcode = 'invalid_parameter_value', hint = 'already_replied';
  end if;

  v_reply := nullif(btrim(coalesce(p_reply, '')), '');
  if v_reply is null then
    raise exception 'A reply cannot be empty'
      using errcode = 'invalid_parameter_value', hint = 'reply_blank';
  end if;
  if length(v_reply) > 2000 then
    raise exception 'That reply is too long'
      using errcode = 'invalid_parameter_value', hint = 'too_long';
  end if;

  update reviews
     set reply = v_reply, replied_at = now()
   where id = p_review_id;
end;

