procedure:public.reprice_job(uuid).source_code:
declare
  v_job   jobs%rowtype;
  v_quote uuid;
begin
  select * into v_job from jobs where id = p_job_id for update;
  if not found then
    raise exception 'Job not found' using errcode = 'no_data_found';
  end if;

  -- SECURITY DEFINER, so current_user is always postgres in here and a
  -- trusted-context check would be true for everyone. The caller's own identity
  -- is the only predicate that means anything.
  if v_job.customer_id <> auth.uid() and not is_admin() then
    raise exception 'Only the job owner may reprice this job' using errcode = '42501';
  end if;

  if v_job.diagnosis_id is null then
    raise exception 'This job has not been diagnosed yet'
      using errcode = 'invalid_parameter_value';
  end if;

  -- Repricing a job that is already out with pros, assigned, or finished would
  -- move a number people have already acted on.
  if v_job.status not in ('draft', 'pending_diagnosis', 'priced') then
    raise exception 'This job can no longer be repriced'
      using errcode = 'invalid_parameter_value';
  end if;

  -- The engine reads its rates from versioned rows and computes the money
  -- itself. Nothing on this path carries an amount, and the old quote is left
  -- untouched — price_quotes are immutable, so the customer can always see what
  -- they were originally shown.
  v_quote := lock_job_price(p_job_id, v_job.diagnosis_id);
  return v_quote;
end;

