  if is_trusted_context() or is_admin() then
    return new;
  end if;
  -- Neither party may attach or swap the engine's price quote.
  new.price_quote_id := old.price_quote_id;

  if auth.uid() = old.pro_id then
    new.approved_by := old.approved_by;
    new.approved_at := old.approved_at;
    if new.status in ('approved','charged') then
      raise exception 'A pro cannot approve their own scope change' using errcode = '42501';
