procedure:public.select_pro_and_create_b.source_code:
declare
  v_caller       uuid := auth.uid();
  v_job          jobs%rowtype;
  v_match        job_matches%rowtype;
  v_quote        price_quotes%rowtype;
  v_existing     bookings%rowtype;
  v_booking_id   uuid;
  v_block_range  tstzrange;
  v_prep         interval := interval '30 minutes';
  v_window       interval;
  v_attempt      int;
begin
  if v_caller is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select b.* into v_existing
  from bookings b
  join audit_events a
    on a.entity_id = b.id
   and a.action = 'booking.created'
   and a.metadata ->> 'idempotency_key' = p_idempotency_key
  limit 1;

  if found then
    return query select v_existing.id, v_existing.status, false;
    return;
  end if;

  select * into v_job from jobs where id = p_job_id for update;
  if not found then
    raise exception 'Job not found' using errcode = 'no_data_found';
  end if;
  if v_job.customer_id <> v_caller then
    raise exception 'Only the job owner may select a pro' using errcode = '42501';
  end if;
  if v_job.status <> 'published' then
    raise exception 'Job is no longer open for selection (status %)', v_job.status
      using errcode = 'invalid_parameter_value';
  end if;

  select * into v_match from job_matches where id = p_match_id for update;
  if not found or v_match.job_id <> p_job_id then
    raise exception 'Match does not belong to this job' using errcode = 'no_data_found';
  end if;
  if v_match.status not in ('interested', 'shortlisted', 'customer_viewed') then
    raise exception 'That pro has not expressed interest in this job'
      using errcode = 'invalid_parameter_value';
  end if;
  if v_match.available_start_at is null then
    raise exception 'That pro has not confirmed an availability slot'
      using errcode = 'invalid_parameter_value';
  end if;

  if not exists (select 1 from eligible_pros_for_job(p_job_id) e where e.pro_id = v_match.pro_id) then
    raise exception 'That pro is no longer eligible for this job'
      using errcode = 'invalid_parameter_value';
  end if;

  if v_job.price_quote_id is null then
    raise exception 'Job has no locked price' using errcode = 'invalid_parameter_value';
  end if;
  select * into v_quote from price_quotes where id = v_job.price_quote_id;

  -- Configurable, not hard-coded: the window is a versioned business rule.
  v_window := coalesce(
    p_decline_window,
    make_interval(mins => coalesce(
      business_rule_int(active_business_rule_set(), 'pro_decline_window_minutes')::int, 120))
  );

  insert into bookings (
    job_id, match_id, customer_id, pro_id, category_id, price_quote_id,
    status, scheduled_start, scheduled_end, address_id, service_location,
    business_rule_set_id, cancellation_policy_id, decline_deadline
  ) values (
    v_job.id, v_match.id, v_job.customer_id, v_match.pro_id, v_job.category_id,
    v_job.price_quote_id, 'pending_pro_confirmation',
    v_match.available_start_at,
    v_match.available_start_at + make_interval(mins => v_job.estimated_duration_minutes),
    v_job.address_id, v_job.service_location,
    v_quote.business_rule_set_id,
    (select id from cancellation_policies where status = 'active' limit 1),
    now() + v_window
  )
  returning id into v_booking_id;

  v_block_range := tstzrange(
    v_match.available_start_at - v_prep,
    v_match.available_start_at + make_interval(mins => v_job.estimated_duration_minutes) + v_prep,
    '[)'
  );
  insert into pro_time_blocks (pro_id, booking_id, kind, time_range)
  values (v_match.pro_id, v_booking_id, 'booking', v_block_range);

  update job_matches set status = 'selected', updated_at = now() where id = v_match.id;
  update job_matches
     set status = 'not_selected', updated_at = now()
   where job_id = p_job_id and id <> v_match.id
     and status not in ('withdrawn', 'expired', 'not_selected');

  update jobs set status = 'pending_selection', closed_at = now(), updated_at = now()
   where id = p_job_id;

  update soft_holds set released_at = now() where job_id = p_job_id and released_at is null;
  delete from pro_time_blocks
   where kind = 'soft_hold'
     and hold_id in (select id from soft_holds where job_id = p_job_id);

  -- Versioned evidence of this attempt, kept whatever the outcome.
  select coalesce(max(attempt_number), 0) + 1 into v_attempt
    from selection_attempts where job_id = p_job_id;
  insert into selection_attempts (job_id, match_id, pro_id, booking_id, attempt_number)
  values (p_job_id, p_match_id, v_match.pro_id, v_booking_id, v_attempt);

  insert into booking_status_history (booking_id, actor_id, previous_status, new_status, note)
  values (v_booking_id, v_caller, null, 'pending_pro_confirmation', 'Customer selected pro');

  insert into job_match_events (match_id, actor_id, previous_status, new_status, note)
  values (v_match.id, v_caller, v_match.status, 'selected', 'Selected by customer');

  insert into audit_events (actor_id, action, entity_type, entity_id, metadata)
  values (v_caller, 'booking.created', 'booking', v_booking_id,
    jsonb_build_object('idempotency_key', p_idempotency_key, 'job_id', p_job_id,
                       'match_id', p_match_id, 'pro_id', v_match.pro_id,
                       'price_quote_id', v_job.price_quote_id, 'attempt', v_attempt));

  -- The selected pro is told; the losers are told the job closed.
  perform queue_booking_notification(v_booking_id, v_match.pro_id, 'pro_selected', 'high');
  insert into notification_outbox (recipient_user_id, event_type, entity_type, entity_id,
                                   event_version, priority, payload)
  select m.pro_id, 'job_closed', 'job', p_job_id, v_attempt, 'normal',
         jsonb_build_object('job_id', p_job_id)
  from job_matches m
  where m.job_id = p_job_id and m.id <> v_match.id and m.status = 'not_selected'
  on conflict (recipient_user_id, event_type, entity_id, event_version) do nothing;

  return query select v_booking_id, 'pending_pro_confirmation'::booking_status, true;
end;

procedure:public.select_pro_and_create_b.definition:
CREATE OR REPLACE FUNCTION public.select_pro_and_create_booking(p_job_id uuid, p_match_id uuid, p_idempotency_key text, p_decline_window interval DEFAULT NULL::interval)
 RETURNS TABLE(booking_id uuid, booking_status public.booking_status, was_created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller       uuid := auth.uid();
  v_job          jobs%rowtype;
  v_match        job_matches%rowtype;
  v_quote        price_quotes%rowtype;
  v_existing     bookings%rowtype;
  v_booking_id   uuid;
  v_block_range  tstzrange;
  v_prep         interval := interval '30 minutes';
  v_window       interval;
  v_attempt      int;
begin
  if v_caller is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  select b.* into v_existing
  from bookings b
  join audit_events a
    on a.entity_id = b.id
   and a.action = 'booking.created'
   and a.metadata ->> 'idempotency_key' = p_idempotency_key
  limit 1;

  if found then
    return query select v_existing.id, v_existing.status, false;
    return;
  end if;

  select * into v_job from jobs where id = p_job_id for update;
  if not found then
    raise exception 'Job not found' using errcode = 'no_data_found';
  end if;
  if v_job.customer_id <> v_caller then
    raise exception 'Only the job owner may select a pro' using errcode = '42501';
  end if;
  if v_job.status <> 'published' then
    raise exception 'Job is no longer open for selection (status %)', v_job.status
      using errcode = 'invalid_parameter_value';
  end if;

  select * into v_match from job_matches where id = p_match_id for update;
  if not found or v_match.job_id <> p_job_id then
    raise exception 'Match does not belong to this job' using errcode = 'no_data_found';
  end if;
  if v_match.status not in ('interested', 'shortlisted', 'customer_viewed') then
    raise exception 'That pro has not expressed interest in this job'
      using errcode = 'invalid_parameter_value';
  end if;
  if v_match.available_start_at is null then
    raise exception 'That pro has not confirmed an availability slot'
      using errcode = 'invalid_parameter_value';
  end if;

  if not exists (select 1 from eligible_pros_for_job(p_job_id) e where e.pro_id = v_match.pro_id) then
    raise exception 'That pro is no longer eligible for this job'
      using errcode = 'invalid_parameter_value';
  end if;

  if v_job.price_quote_id is null then
    raise exception 'Job has no locked price' using errcode = 'invalid_parameter_value';
  end if;
  select * into v_quote from price_quotes where id = v_job.price_quote_id;

  -- Configurable, not hard-coded: the window is a versioned business rule.
  v_window := coalesce(
    p_decline_window,
    make_interval(mins => coalesce(
      business_rule_int(active_business_rule_set(), 'pro_decline_window_minutes')::int, 120))
  );

  insert into bookings (
    job_id, match_id, customer_id, pro_id, category_id, price_quote_id,
    status, scheduled_start, scheduled_end, address_id, service_location,
    business_rule_set_id, cancellation_policy_id, decline_deadline
  ) values (
    v_job.id, v_match.id, v_job.customer_id, v_match.pro_id, v_job.category_id,
    v_job.price_quote_id, 'pending_pro_confirmation',
    v_match.available_start_at,
    v_match.available_start_at + make_interval(mins => v_job.estimated_duration_minutes),
    v_job.address_id, v_job.service_location,
    v_quote.business_rule_set_id,
    (select id from cancellation_policies where status = 'active' limit 1),
    now() + v_window
  )
  returning id into v_booking_id;

  v_block_range := tstzrange(
    v_match.available_start_at - v_prep,
    v_match.available_start_at + make_interval(mins => v_job.estimated_duration_minutes) + v_prep,
    '[)'
  );
  insert into pro_time_blocks (pro_id, booking_id, kind, time_range)
  values (v_match.pro_id, v_booking_id, 'booking', v_block_range);

  update job_matches set status = 'selected', updated_at = now() where id = v_match.id;
  update job_matches
     set status = 'not_selected', updated_at = now()
   where job_id = p_job_id and id <> v_match.id
     and status not in ('withdrawn', 'expired', 'not_selected');

  update jobs set status = 'pending_selection', closed_at = now(), updated_at = now()
   where id = p_job_id;

  update soft_holds set released_at = now() where job_id = p_job_id and released_at is null;
  delete from pro_time_blocks
   where kind = 'soft_hold'
     and hold_id in (select id from soft_holds where job_id = p_job_id);

  -- Versioned evidence of this attempt, kept whatever the outcome.
  select coalesce(max(attempt_number), 0) + 1 into v_attempt
    from selection_attempts where job_id = p_job_id;
  insert into selection_attempts (job_id, match_id, pro_id, booking_id, attempt_number)
  values (p_job_id, p_match_id, v_match.pro_id, v_booking_id, v_attempt);

  insert into booking_status_history (booking_id, actor_id, previous_status, new_status, note)
  values (v_booking_id, v_caller, null, 'pending_pro_confirmation', 'Customer selected pro');

  insert into job_match_events (match_id, actor_id, previous_status, new_status, note)
  values (v_match.id, v_caller, v_match.status, 'selected', 'Selected by customer');

  insert into audit_events (actor_id, action, entity_type, entity_id, metadata)
  values (v_caller, 'booking.created', 'booking', v_booking_id,
    jsonb_build_object('idempotency_key', p_idempotency_key, 'job_id', p_job_id,
                       'match_id', p_match_id, 'pro_id', v_match.pro_id,
                       'price_quote_id', v_job.price_quote_id, 'attempt', v_attempt));

  -- The selected pro is told; the losers are told the job closed.
  perform queue_booking_notification(v_booking_id, v_match.pro_id, 'pro_selected', 'high');
  insert into notification_outbox (recipient_user_id, event_type, entity_type, entity_id,
                                   event_version, priority, payload)
  select m.pro_id, 'job_closed', 'job', p_job_id, v_attempt, 'normal',
         jsonb_build_object('job_id', p_job_id)
  from job_matches m
  where m.job_id = p_job_id and m.id <> v_match.id and m.status = 'not_selected'
  on conflict (recipient_user_id, event_type, entity_id, event_version) do nothing;

  return query select v_booking_id, 'pending_pro_confirmation'::booking_status, true;
end;
$function$

procedure:public.send_chat_message(uuid,.source_code:
-- The RETURNS TABLE names (conversation_id, created_at) are also column names
-- on chat_messages, and an ON CONFLICT target cannot be table-qualified. Bare
-- names here therefore mean the COLUMN; every value this function computes is
-- held in a v_ local and returned explicitly at the end.
#variable_conflict use_column
declare
  v_conversation uuid;
  v_booking      bookings%rowtype;
  v_recipient    uuid;
  v_body         text;
  v_id           uuid;
  v_created      timestamptz;
begin
  select * into v_booking from bookings where id = p_booking_id;
  if not found then
    raise exception 'No such booking' using errcode = 'no_data_found';
  end if;

  if v_booking.customer_id is distinct from auth.uid()
     and v_booking.pro_id is distinct from auth.uid() then
    raise exception 'Only the customer and the assigned pro can send messages here'
      using errcode = '42501';
  end if;

  -- Reading stays open forever; sending closes 30 days after the booking ends.
  if not chat_sending_open(p_booking_id) then
    raise exception
      'This conversation is read-only: messages closed 30 days after the booking ended'
      using errcode = 'invalid_parameter_value', hint = 'chat_window_closed';
  end if;

  if p_client_key is null or length(btrim(p_client_key)) = 0 then
    raise exception 'A message needs an idempotency key'
      using errcode = 'invalid_parameter_value';
  end if;

  v_body := btrim(coalesce(p_body, ''));
  if length(v_body) = 0 then
    raise exception 'A message cannot be empty'
      using errcode = 'invalid_parameter_value', hint = 'message_blank';
  end if;
  if length(v_body) > 2000 then
    raise exception 'A message cannot be longer than 2000 characters'
      using errcode = 'invalid_parameter_value', hint = 'message_too_long';
  end if;

  v_conversation := open_conversation(p_booking_id);

  insert into chat_messages (conversation_id, sender_id, body, client_key)
  values (v_conversation, auth.uid(), v_body, btrim(p_client_key))
  on conflict (conversation_id, sender_id, client_key) do nothing
  returning id, chat_messages.created_at into v_id, v_created;

  if v_id is null then
    select m.id, m.created_at into v_id, v_created
      from chat_messages m
     where m.conversation_id = v_conversation
       and m.sender_id = auth.uid()
       and m.client_key = btrim(p_client_key);

    return query select v_id, v_conversation, v_created, true;
    return;
  end if;

  update conversations set last_message_at = v_created where id = v_conversation;

  v_recipient := case when v_booking.customer_id = auth.uid()
                      then v_booking.pro_id else v_booking.customer_id end;

  insert into notification_outbox (recipient_user_id, event_type, entity_type,
                                   entity_id, event_version, priority, payload)
  values (v_recipient, 'chat_message', 'chat_message', v_id, 1, 'normal',
          jsonb_build_object(
            'message_id', v_id,
            'conversation_id', v_conversation,
            'booking_id', p_booking_id,
            'sender_id', auth.uid(),
            'preview', left(v_body, 80)))
  on conflict (recipient_user_id, event_type, entity_id, event_version) do nothing;

  return query select v_id, v_conversation, v_created, false;
end;

