procedure:public.set_default_payment_met.source_code:
declare
  v_row payment_methods%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;

  select * into v_row from payment_methods where id = p_payment_method_id;

  -- Same message whether the card belongs to somebody else or does not exist:
  -- distinguishing them tells a caller which ids are real.
  if not found or v_row.profile_id is distinct from auth.uid() then
    raise exception 'No such payment method' using errcode = 'no_data_found';
  end if;

  if v_row.detached_at is not null then
    raise exception 'That card has been removed'
      using errcode = 'invalid_parameter_value', hint = 'detached';
  end if;

  update payment_methods set is_default = false, updated_at = now()
   where profile_id = auth.uid() and is_default and id <> p_payment_method_id;

  update payment_methods set is_default = true, updated_at = now()
   where id = p_payment_method_id;
end;

