procedure:public.start_booking_phase(uui.source_code:
declare
  v_booking bookings%rowtype;
  v_title   text;
  v_id      uuid;
begin
  select * into v_booking from bookings where id = p_booking_id;
  if not found then
    raise exception 'No such booking' using errcode = 'no_data_found';
  end if;

  if v_booking.pro_id is distinct from auth.uid() then
    raise exception 'Only the assigned pro can record progress'
      using errcode = '42501';
  end if;

  -- Progress on a job that has not started, or has already ended, is not
  -- progress. This is the same set the materials flow treats as active work.
  if v_booking.status not in ('in_progress', 'en_route', 'completion_submitted') then
    raise exception 'Progress can only be recorded on a job that is underway'
      using errcode = 'invalid_parameter_value', hint = 'not_underway';
  end if;

  v_title := btrim(coalesce(p_title, ''));
  if length(v_title) = 0 then
    raise exception 'Describe what you have started'
      using errcode = 'invalid_parameter_value', hint = 'title_blank';
  end if;
  if length(v_title) > 200 then
    raise exception 'That description is too long'
      using errcode = 'invalid_parameter_value', hint = 'title_too_long';
  end if;

  insert into booking_phases (booking_id, title) values (p_booking_id, v_title)
  returning id into v_id;

  insert into notification_outbox (recipient_user_id, event_type, entity_type,
                                   entity_id, event_version, priority, payload)
  values (v_booking.customer_id, 'phase_started', 'booking_phase', v_id, 1, 'normal',
          jsonb_build_object('booking_id', p_booking_id, 'phase_id', v_id))
  on conflict (recipient_user_id, event_type, entity_id, event_version) do nothing;

  return v_id;
end;

