procedure:public.submit_review(uuid,inte.source_code:
declare
  v_booking bookings%rowtype;
  v_id      uuid;
  v_comment text;
begin
  select * into v_booking from bookings where id = p_booking_id;
  if not found then
    raise exception 'No such booking' using errcode = 'no_data_found';
  end if;

  if v_booking.customer_id is distinct from auth.uid() then
    raise exception 'Only the customer on this booking can review it'
      using errcode = '42501';
  end if;

  -- Only after the work happened. A review before completion is a review of
  -- nothing, and would let a customer rate a pro for declining.
  if v_booking.status <> 'completed' then
    raise exception 'You can review this booking once the job is complete'
      using errcode = 'invalid_parameter_value', hint = 'not_completed';
  end if;

  if p_rating is null or p_rating < 1 or p_rating > 5 then
    raise exception 'A rating must be between 1 and 5'
      using errcode = 'invalid_parameter_value', hint = 'bad_rating';
  end if;

  v_comment := nullif(btrim(coalesce(p_comment, '')), '');
  if v_comment is not null and length(v_comment) > 2000 then
    raise exception 'That review is too long'
      using errcode = 'invalid_parameter_value', hint = 'too_long';
  end if;

  insert into reviews (booking_id, reviewer_id, reviewee_id, rating, comment)
  values (p_booking_id, auth.uid(), v_booking.pro_id, p_rating, v_comment)
  on conflict (booking_id) do nothing
  returning id into v_id;

  if v_id is null then
    raise exception 'You have already reviewed this booking'
      using errcode = 'unique_violation', hint = 'already_reviewed';
  end if;

  insert into notification_outbox (recipient_user_id, event_type, entity_type,
                                   entity_id, event_version, priority, payload)
  values (v_booking.pro_id, 'review_received', 'review', v_id, 1, 'normal',
          jsonb_build_object('review_id', v_id, 'booking_id', p_booking_id,
                             'rating', p_rating))
  on conflict (recipient_user_id, event_type, entity_id, event_version) do nothing;

  return v_id;
end;

