procedure:public.submit_scope_change(uui.source_code:
declare
  v_sc       scope_changes%rowtype;
  v_booking  bookings%rowtype;
  v_job      jobs%rowtype;
  v_prs      uuid := active_pricing_rule_set();
  v_minutes  int;
  v_prio_bp  int := 0;
  v_pay_base bigint;
  v_pay      bigint;
  v_labour   bigint;
  v_comm     bigint;
  v_fee_bp   bigint;
  v_fee      bigint;
  v_quote_id uuid;
begin
  select * into v_sc from scope_changes where id = p_scope_change_id for update;
  if not found then
    raise exception 'Scope change not found' using errcode = 'no_data_found';
  end if;

  if v_sc.pro_id <> auth.uid() then
    raise exception 'Only the pro who raised this scope change may submit it'
      using errcode = '42501';
  end if;

  -- Idempotent: a retry or a double tap returns the quote already produced.
  if v_sc.price_quote_id is not null and v_sc.status = 'submitted' then
    return v_sc.price_quote_id;
  end if;

  if v_sc.status not in ('draft','rejected') then
    raise exception 'A scope change can only be submitted while draft or after rejection (status %)',
      v_sc.status using errcode = 'invalid_parameter_value';
  end if;

  if v_sc.additional_minutes is null or v_sc.additional_minutes <= 0 then
    raise exception 'Additional minutes are required before pricing'
      using errcode = 'invalid_parameter_value';
  end if;

  select * into v_booking from bookings where id = v_sc.booking_id;
  if v_booking.status not in ('confirmed','in_progress') then
    raise exception 'Scope changes apply only to an active booking (status %)',
      v_booking.status using errcode = 'invalid_parameter_value';
  end if;

  -- Fail closed on a missing or unusable snapshot.
  if v_booking.additional_time_rate_cents is null then
    raise exception
      'This booking has no additional-time rate. The pro must publish a rate '
      'for this category before extra work can be priced.'
      using errcode = 'invalid_parameter_value';
  end if;
  if v_booking.commission_bp is null
     or v_booking.commission_bp < 0
     or v_booking.commission_bp >= 10000 then
    raise exception 'This booking has no usable commission snapshot'
      using errcode = 'invalid_parameter_value';
  end if;

  select * into v_job from jobs where id = v_booking.job_id;
  if not found then
    raise exception 'Job not found for this booking' using errcode = 'no_data_found';
  end if;

  -- Every input comes from the snapshot. The live rate card is not consulted at
  -- all, so retuning it cannot move an agreed booking's additional-time charge.
  v_minutes := v_sc.additional_minutes;
  v_prio_bp := coalesce(v_booking.priority_uplift_bp, 0);

  -- 1. pro-rata from the snapshotted rate, from the first minute.
  v_pay_base := (v_booking.additional_time_rate_cents * v_minutes) / 60;
  -- 2. the priority uplift applies to the pro's pay.
  v_pay := v_pay_base + (v_pay_base * v_prio_bp) / 10000;

  if v_pay <= 0 then
    raise exception 'Additional labour priced at zero; refusing to create a quote'
      using errcode = 'invalid_parameter_value';
  end if;

  -- 3+4. Gross up, truncating to whole cents. Integer arithmetic throughout, so
  -- the result is deterministic and identical for identical inputs. The pro's
  -- pay is already whole cents and is the promised figure; the customer's
  -- labour truncates DOWN, which means the fractional cent is absorbed by the
  -- platform's commission and never taken from the pro or added to the
  -- customer.
  v_labour := (v_pay * 10000) / (10000 - v_booking.commission_bp);

  -- 5. Commission is the remainder, by construction. Deriving it any other way
  -- would break price_quotes_payout_within_labor, which requires
  -- payout + commission = labour exactly.
  v_comm := v_labour - v_pay;

  v_fee_bp := coalesce(
    business_rule_int(v_booking.business_rule_set_id, 'customer_fee_bp'), 1500);
  v_fee := (v_labour * v_fee_bp) / 10000;

  insert into price_quotes (
    category_id, priority, pricing_rule_set_id, business_rule_set_id,
    billable_minutes, calculation, currency,
    labor_amount_cents, customer_fee_cents,
    platform_commission_cents, expected_payout_cents
  ) values (
    v_job.category_id, v_job.final_priority, v_prs, v_booking.business_rule_set_id,
    v_minutes,
    jsonb_build_object(
      'kind',                     'scope_change',
      'scope_change_id',          v_sc.id,
      'model',                    'pro_rate_gross_up_v1',
      'pro_rate_cents_per_hour',  v_booking.additional_time_rate_cents,
      'billable_minutes',         v_minutes,
      'pro_pay_base_cents',       v_pay_base,
      'priority',                 v_job.final_priority,
      'priority_adjustment_bp',   v_prio_bp,
      'pro_pay_cents',            v_pay,
      'commission_bp',            v_booking.commission_bp,
      'customer_labour_cents',    v_labour,
      'platform_commission_cents', v_comm,
      'customer_fee_bp',          v_fee_bp,
      'callout_minimum_applied',  false,
      -- Captured as the pro's justification. It does NOT multiply the amount.
      'observed_complexity',      coalesce(v_sc.observed_complexity, 'medium'),
      'complexity_affects_amount', false
    ),
    coalesce(v_booking.rate_currency, 'USD'),
    v_labour, v_fee, v_comm, v_pay
  )
  returning id into v_quote_id;

  update scope_changes
     set price_quote_id   = v_quote_id,
         status           = 'submitted',
         submitted_at     = now(),
         rejected_at      = null,
         rejection_reason = null,
         updated_at       = now()
   where id = p_scope_change_id;

  insert into audit_events (actor_id, actor_kind, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'user', 'scope_change.submitted', 'scope_change', p_scope_change_id,
          jsonb_build_object('booking_id', v_sc.booking_id,
                             'price_quote_id', v_quote_id,
                             'additional_minutes', v_minutes));

  return v_quote_id;
end;

