procedure:public.submit_verification_doc.source_code:
declare
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Sign in first' using errcode = '42501';
  end if;

  if not exists (select 1 from pro_profiles where profile_id = auth.uid()) then
    raise exception 'Only a pro can submit verification documents'
      using errcode = '42501';
  end if;

  if p_kind not in ('identity','background_check','license','insurance',
                    'business_registration') then
    raise exception 'Unknown document type %', p_kind
      using errcode = 'invalid_parameter_value', hint = 'bad_kind';
  end if;

  if p_storage_path is null or length(btrim(p_storage_path)) = 0 then
    raise exception 'A document is required'
      using errcode = 'invalid_parameter_value', hint = 'no_document';
  end if;

  -- The path must be inside the caller's own folder. The storage policy already
  -- enforces this on upload; checking it again here stops a row pointing at
  -- somebody else's document even if it was written by some other route.
  if split_part(btrim(p_storage_path), '/', 1) <> auth.uid()::text then
    raise exception 'That document does not belong to you'
      using errcode = '42501';
  end if;

  -- Re-submitting replaces the previous attempt and returns it to pending: a
  -- rejected document that is corrected must be looked at again, and an
  -- approved one that is replaced is no longer the document that was approved.
  insert into pro_verifications (pro_id, kind, state, storage_path, issued_at, expires_at)
  values (auth.uid(), p_kind, 'pending', btrim(p_storage_path), p_issued_at, p_expires_at)
  on conflict (pro_id, kind) do update
     set state           = 'pending',
         storage_path    = excluded.storage_path,
         issued_at       = excluded.issued_at,
         expires_at      = excluded.expires_at,
         reviewed_by     = null,
         reviewed_at     = null,
         rejection_reason = null,
         updated_at      = now()
  returning id into v_id;

  insert into audit_events (actor_id, actor_kind, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'user', 'verification.submitted', 'pro_verification', v_id,
          jsonb_build_object('kind', p_kind));

  return v_id;
end;

