procedure:public.unsave_pro(uuid).source_code:
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  -- Deletes exactly one row from one table. Jobs and bookings reference
  -- nothing here and there is no cascade out of this table, so unsaving a pro
  -- cannot disturb work already under way with them.
  delete from pro_favourites where customer_id = v_uid and pro_id = p_pro_id;
  return true;
end;

