procedure:public.update_my_location(uuid.source_code:
declare
  v_booking bookings%rowtype;
begin
  select * into v_booking from bookings where id = p_booking_id;
  if not found then
    raise exception 'No such booking' using errcode = 'no_data_found';
  end if;

  if v_booking.pro_id is distinct from auth.uid() then
    raise exception 'Only the assigned pro can share their location'
      using errcode = '42501';
  end if;

  -- The one status where a customer has a reason to see it.
  if v_booking.status <> 'en_route' then
    raise exception 'Location is shared only while you are on the way'
      using errcode = 'invalid_parameter_value', hint = 'not_en_route';
  end if;

  if p_latitude is null or p_longitude is null
     or p_latitude not between -90 and 90
     or p_longitude not between -180 and 180 then
    raise exception 'Those coordinates are not valid'
      using errcode = 'invalid_parameter_value', hint = 'bad_coordinates';
  end if;

  update bookings
     set pro_location = st_setsrid(st_makepoint(p_longitude, p_latitude), 4326)::geography,
         pro_location_at = now()
   where id = p_booking_id;
end;

